"use client"

import React, { useState } from "react"
import { CodeIcon, SidebarIcon } from "@phosphor-icons/react"
import {
    TabsExtended,
    TabsIndicator,
    TabsList,
    TabsListContainer,
    TabsTab,
} from "@sb-components/atoms/navigation/Tabs/Tabs"
import { StackV } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — faithful port of
 * `@/components/blocks/rendering/MarkdownContent/CodePreviewTabs`. Authored in
 * Storybook (not `src`); synced back to `src` later.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props for {@link CodePreviewTabs}. */
export interface CodePreviewTabsProps {
    /** Live render (the rendered demo pane). */
    preview: React.ReactNode
    /** Source code panel (Shiki-highlighted). */
    code: React.ReactNode
    /** Where this sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Presentational **[ Preview | Code ]** tabs, self-contained (`TabsExtended`
 * atom root + house tab parts + phosphor icons). Preview is selected first so
 * the learner sees the rendered result, then flips to the code. Shared by
 * `TabsBlock` (the `:::tab` directive's dual panes) so the tab shell stays
 * identical and depends on NO layout component.
 * @param props - {@link CodePreviewTabsProps}
 */
export const CodePreviewTabs = ({ preview, code, classNames }: CodePreviewTabsProps) => {
    const [tab, setTab] = useState<"preview" | "code">("preview")
    const panes = [
        () => (
            <TabsExtended
                selectedKey={tab}
                variant="secondary"
                onSelectionChange={(key) => setTab(key === "code" ? "code" : "preview")}
            >
                <TabsListContainer className="w-fit">
                    <TabsList aria-label="Preview / Code" className="w-fit">
                        <TabsTab
                            id="preview"
                            data-principle="icon-text" className="gap-1 data-[selected=true]:text-accent-soft-foreground"
                        >
                            <SidebarIcon />
                            Preview
                            <TabsIndicator />
                        </TabsTab>
                        <TabsTab
                            id="code"
                            data-principle="icon-text" className="gap-1 data-[selected=true]:text-accent-soft-foreground"
                        >
                            <CodeIcon />
                            Code
                            <TabsIndicator />
                        </TabsTab>
                    </TabsList>
                </TabsListContainer>
            </TabsExtended>
        ),
        () => (
            <div className={tab === "preview" ? "rounded-xl border border-divider p-3" : undefined}>
                {tab === "preview" ? preview : code}
            </div>
        ),
    ]
    return (
        <StackV
            gap={3}
            classNames={classNames}
            items={panes}
        />
    )
}

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FoundationCategoryList` — the Foundations content library's browse-and-drill-in
 * list: joined rows with a thumbnail, title, one-line description and a trailing
 * caret, plus a pager once there is more than one page. Loading swaps row content
 * to shimmer; the `Empty` state replaces the rows with an `EmptyState` (worded by
 * whether a search query drove the empty result), both bounded inside the same
 * `SurfaceCardList` surface.
 */

/** One category row — plain data; the block resolves the thumbnail chain and builds the wording. */
export interface FoundationCategoryListItem {
    /** Stable id — also what `onSelectCategory` fires with. */
    id: string
    /** Category title. */
    title: string
    /** One-line summary, shown as the row's subtitle. */
    description?: string
    /** Underlying tech/brand mark — rides as the `Image` atom's `fallbackSrc` (see file header). */
    logoSrc?: string
    /** Dedicated category thumbnail — wins over `logoSrc` when present (see file header). */
    thumbnailUrl?: string
}

/** Page state for the list's own pager — omit entirely when the caller has only one page. */
export interface FoundationCategoryListPagination {
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the reader picked. */
    onPageChange: (pageNumber: number) => void
}

/** Props for {@link FoundationCategoryList}. */
export interface FoundationCategoryListProps {
    /** The current page's categories, in display order. */
    categories: Array<FoundationCategoryListItem>
    /**
     * Current search text driving which empty reason applies when `categories`
     * is empty (see file header, judgement 2). Not rendered as a field by this
     * block — the search input itself is `FoundationCategorySearchBar`'s job.
     */
    searchQuery?: string
    /** Fired with a category's id on ANY row press. */
    onSelectCategory: (id: string) => void
    /** Page nav state. Omit → no pager, even with a full page of rows. */
    pagination?: FoundationCategoryListPagination
    /**
     * `true` → the list draws its own row mirror. `categories` empty while
     * loading (§12c) → guesses 3 rows, this composite's siblings' SSOT convention.
     */
    isSkeleton?: boolean
}

/** The library-itself-is-empty title — no search was involved, so no "try another word" hint applies. Ported verbatim from `foundations.emptyCategories`. */
const LIBRARY_EMPTY_TITLE = "No Foundations topics yet."

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler or a thumbnail. */
const SKELETON_CATEGORIES: Array<FoundationCategoryListItem> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
}))

/**
 * Resolves the thumbnail-priority chain (see file header, judgement 1) into the
 * `Image` atom's own `src`/`fallbackSrc` pair — a naming decision, not a second
 * rendering path.
 */
const resolveThumbnail = (category: FoundationCategoryListItem): { src?: string; fallbackSrc?: string } =>
    category.logoSrc
        ? { src: category.logoSrc, fallbackSrc: category.thumbnailUrl }
        : { src: category.thumbnailUrl, fallbackSrc: undefined }

interface NoCategoriesEmptyStateProps {
    hasQuery: boolean
    searchQuery?: string
}
const NoCategoriesEmptyState = ({ hasQuery, searchQuery }: NoCategoriesEmptyStateProps) => (
    <EmptyState
        icon={hasQuery ? MagnifyingGlassIcon : undefined}
        title={hasQuery ? `No topics match "${searchQuery?.trim()}".` : LIBRARY_EMPTY_TITLE}
    />
)

/**
 * The Foundations library's browse-and-drill-in list. See the file header for
 * the thumbnail-priority chain, the two empty reasons, and why loading stays a
 * state of the same leaf rather than earning its own.
 *
 * @param props - {@link FoundationCategoryListProps}
 */
const FoundationCategoryList = ({
    categories,
    searchQuery,
    onSelectCategory,
    pagination,
    isSkeleton = false,
}: FoundationCategoryListProps) => {
    // Empty while loading (no real categories yet) → guess 3 rows, keeping the
    // right shape for when real data lands (§8). Once real `categories` exist,
    // keep the EXACT row count already there.
    const usingPlaceholders = isSkeleton && categories.length === 0
    const source = usingPlaceholders ? SKELETON_CATEGORIES : categories

    const rows: Array<SurfaceCardListItem> = source.map((category) => {
        const { src, fallbackSrc } = resolveThumbnail(category)
        return {
            key: category.id,
            leading: () => (
                <div className="size-10 shrink-0">
                    <Image
                        src={src}
                        fallbackSrc={fallbackSrc}
                        alt={category.title}
                        ratio="square"
                        radius="md"
                        isSkeleton={isSkeleton}

                    />
                </div>
            ),
            title: category.title,
            subtitle: category.description,
            // Every real row navigates — a constant of this domain, never conditional
            // (see file header, judgement 3).
            trailingIcon: CaretRightIcon,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectCategory(category.id),
        }
    })

    // Which of the two empty reasons applies (see file header, judgement 2) —
    // never during the skeleton branch, where "empty" just means "not loaded yet".
    const hasQuery = (searchQuery?.trim().length ?? 0) > 0
    const emptyState = !isSkeleton && categories.length === 0
        ? () => <NoCategoriesEmptyState hasQuery={hasQuery} searchQuery={searchQuery} />
        : undefined

    // Nothing to page through during the first fetch or an empty result (see
    // file header, judgement on the pager).
    const showPager = !isSkeleton && categories.length > 0 && pagination != null

    return (
        <StackV identity={{ tier: "block", component: "FoundationCategoryList" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <SurfaceCardList

                        isSkeleton={isSkeleton}
                        items={rows}
                        emptyState={emptyState}
                    />
                ),
                ...(showPager
                    ? [
                        () => (
                            <div>
                                <Pagination
                                    currentPage={pagination.currentPage}
                                    totalPages={pagination.totalPages}
                                    onPageChange={pagination.onPageChange}

                                />
                            </div>
                        ),
                    ]
                    : []),
            ]}
        />
    )
}

export { FoundationCategoryList }

import { FunnelSimpleIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { InputSearch } from "@sb-components/atoms/forms"
import { Popover } from "@sb-components/atoms/overlay/Popover/Popover"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { Badge } from "@sb-components/atoms/display/Badge/Badge"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import type { VerdictBandVariant } from "@sb-components/composites/cards/verdict-band"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `MindMapRail` — the keyword lookup pane beside a mind-map canvas: search a term,
 * narrow by popularity tier, pick a result. Two shapes: `Default` (funnel popover
 * closed — loading/empty/populated are states of the single region below the header
 * row, swapped by `AsyncContent`) and `FilterOpen` (the popover panel open, so the
 * tier `ButtonRadioGroup` becomes a real node). The open panel renders through a
 * portal, outside the box `BlockAnatomy` scans.
 */

/** The popularity-tier filter this rail's result list is narrowed by. */
export type MindMapRailTier = "all" | "medium" | "high"

/** One keyword result — plain DATA; the block builds the row's tone and check. */
export interface MindMapRailItem {
    /** Stable id — the React key, and what `onPick` fires with. */
    id: string
    /** The keyword's display label. */
    label: string
    /** Relevance/popularity score in the map (0–100, higher = more central). Drives the row's tone via {@link popularityTone}. */
    popularity: number
    /** Where this keyword sits in the map's hierarchy, e.g. "Networking > TCP > Handshake". */
    breadcrumb: string
}

/** Props for {@link MindMapRail}. */
export interface MindMapRailProps {
    /** Current search text (controlled). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its row is pressed. */
    onPick: (id: string) => void
    /** `true` → this rail's own query/tier fetch is in flight. */
    isLoading: boolean
    /** Accessible name for the search field. */
    ariaLabel: string
    /** Accessible name for the tier radio group inside the funnel popover. */
    tierAriaLabel: string
    /** `true` → the result list renders its own mirror (see file header's loading judgement call). */
    isSkeleton?: boolean
    /** Dev/spec only: pins the funnel popover open (see file header's judgement call). */
    defaultFilterOpen?: boolean
}

/** The block's own wording for the tier filter — never handed in by the caller (§14d.1). */
const TIER_LABEL: Record<MindMapRailTier, string> = {
    all: "All",
    medium: "Medium",
    high: "High",
}

const TIER_ORDER: Array<MindMapRailTier> = ["all", "medium", "high"]

/** Popularity score at/above which a row earns the "hub term" accent band. */
const POPULARITY_HIGH_THRESHOLD = 70
/** Popularity score at/above which a row earns the quieter "worth a look" band. */
const POPULARITY_MEDIUM_THRESHOLD = 35

/** Popularity → row tone — see file header's judgement call for why only two bands exist. */
const popularityTone = (popularity: number): VerdictBandVariant | undefined => {
    if (popularity >= POPULARITY_HIGH_THRESHOLD) return "accent"
    if (popularity >= POPULARITY_MEDIUM_THRESHOLD) return "warning"
    return undefined
}

const FILTER_TRIGGER_LABEL = "Filter"
const FILTER_HEADING = "Popularity"
const SEARCH_PLACEHOLDER = "Search keywords..."
const EMPTY_TITLE_NO_QUERY = "No keywords in this map yet"
const EMPTY_DESCRIPTION_WITH_QUERY = "Try a different keyword or loosen the filter."

/** How many placeholder rows mirror the list while `items` hasn't landed yet. */
const SKELETON_ROW_COUNT = 5

/** Placeholder rows for the loading mirror — no data, no press handler (§12c). */
const skeletonRows = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        title: "",
        subtitle: "",
    }))

/** One real row: label + breadcrumb subtitle, popularity tone band, selection check. */
const resultRow = (item: MindMapRailItem, selectedId: string | undefined, onPick: (id: string) => void): SurfaceCardListItem => ({
    key: item.id,
    title: item.label,
    subtitle: item.breadcrumb,
    metaText: String(item.popularity),
    tone: popularityTone(item.popularity),
    selected: item.id === selectedId,
    onPress: () => onPick(item.id),
})

/**
 * The keyword lookup pane. See the file header for the full contract, the
 * two-leaf boundary, and the judgement calls (tone bands, `defaultFilterOpen`,
 * never-skeletonised header row).
 *
 * @param props - {@link MindMapRailProps}
 */
const MindMapRail = ({
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isLoading,
    ariaLabel,
    tierAriaLabel,
    isSkeleton = false,
    defaultFilterOpen = false,
}: MindMapRailProps) => {
    const hasQuery = query.trim().length > 0
    const isFiltered = tier !== "all"

    const emptyContent: AsyncContentEmptyProps = hasQuery
        ? {
            icon: MagnifyingGlassIcon,
            title: `No keywords match "${query}"`,
            description: EMPTY_DESCRIPTION_WITH_QUERY,

        }
        : {
            title: EMPTY_TITLE_NO_QUERY,

        }

    const rows: Array<SurfaceCardListItem> = items.map((item) => resultRow(item, selectedId, onPick))

    const filterTrigger = (
        <Popover
            triggerLabel={FILTER_TRIGGER_LABEL}
            triggerIcon={FunnelSimpleIcon}
            heading={FILTER_HEADING}
            defaultOpen={defaultFilterOpen}

            content={
                <div>
                    <ButtonRadioGroup
                        ariaLabel={tierAriaLabel}
                        value={tier}
                        onChange={onTier}

                        items={TIER_ORDER.map((key) => ({ value: key, content: TIER_LABEL[key] }))}
                    />
                </div>
            }
        />
    )

    return (
        <StackV
            identity={{ tier: "block", component: "MindMapRail" }}
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        at="sm"
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <div className="min-w-0 flex-1">
                                    <InputSearch
                                        value={query}
                                        onValueChange={onQuery}
                                        placeholder={SEARCH_PLACEHOLDER}
                                        ariaLabel={ariaLabel}

                                    />
                                </div>
                            ),
                            () => (
                                <div>
                                    {/* `Badge` only wraps the trigger when a non-default tier is active — `dot` has
                                        no built-in "hide me" reading the way `count` does (§ Badge file header: count
                                        ≤ 0 hides itself, a bare dot has no such signal), so the ON/OFF state is this
                                        block's own condition instead of a prop the atom could resolve alone. */}
                                    {isFiltered ? <Badge dot>{filterTrigger}</Badge> : filterTrigger}
                                </div>
                            ),
                        ]}
                    />
                ),
                () => (
                    <AsyncContent
                        isLoading={isLoading || isSkeleton}
                        skeleton={() => <SurfaceCardList items={skeletonRows()} isSkeleton />}
                        isEmpty={items.length === 0}
                        emptyContent={emptyContent}

                        content={() => <SurfaceCardList items={rows} />}
                    />
                ),
            ]}
        />
    )
}

export { MindMapRail }

import React from "react"
import { Link as HeroUILink, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `NavLinks` — the desktop primary-route row inside the site's top nav
 * ("Home / Courses / Community / Contact"), one pinned as current. The
 * presentational half of a container: it takes `items` already resolved
 * (label/path/isActive) and an `onNavigate` callback, leaving router wiring to
 * the caller. Rendered with `Link` (HeroUI), not a tab compound — these are
 * real routes, not panels under one ARIA tablist. One leaf, `Row`; the current
 * route is data, so it is a state.
 */

/** One route entry in the nav row — TYPED DOMAIN DATA, never a pre-formatted node. */
export interface NavLinkItem {
    /** Already-localized label, e.g. "Courses". */
    label: string
    /** Route path, also the stable React key (paths are unique by construction). */
    path: string
    /** `true` → rendered as the current-route pill; the caller decides via its own routing. */
    isActive: boolean
}

/** Props for {@link NavLinks}. */
export interface NavLinksProps {
    /** Routes offered, in display order. */
    items: Array<NavLinkItem>
    /** Fired with the pressed item's `path` — the caller owns the actual navigation. */
    onNavigate: (path: string) => void
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The desktop primary-route row. See the file header for why this is the
 * presentational half of the real `NavLinks` container, and why it composes a
 * bare `Link` rather than `Toolbar`/`Tabs`.
 *
 * @param props - {@link NavLinksProps}
 */
const NavLinks = ({ items, onNavigate, classNames }: NavLinksProps) => (
    <div className="hidden @app-md:flex">
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="center"
            classNames={classNames}

            items={items.map((item) => () => (
                <HeroUILink
                    onPress={() => onNavigate(item.path)}
                    aria-current={item.isActive ? "page" : undefined}

                >
                    <span
                        className={cn(
                            "whitespace-nowrap rounded-full px-3 py-2 text-sm transition-colors",
                            item.isActive ? "bg-accent-soft text-accent-soft-foreground" : "text-muted hover:text-foreground",
                        )}
                    >
                        {item.label}
                    </span>
                </HeroUILink>
            ))}
        />
    </div>
)

export { NavLinks }

import React from "react"
import type { ReactNode } from "react"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnrollGate, type EnrollGateProps } from "@sb-components/starci/blocks/learn/EnrollGate/EnrollGate"
import { ContentAiFab } from "@sb-components/starci/blocks/learn/ContentAiFab/ContentAiFab"
import {
    ContentAiSelectionAsk,
    type ContentAiSelectionAskAnchor,
} from "@sb-components/starci/blocks/learn/ContentAiSelectionAsk/ContentAiSelectionAsk"

/**
 * `LearnShell` — the wrapper mounted once per `/learn/**` scope. Five
 * structural leaves, each gaining or losing a whole node:
 *   - `RailSurface`        — rail mounted beside `children`, one floating FAB.
 *   - `NoRailSurface`      — no rail; `children` fills the width.
 *   - `SelectionAskActive` — gains the `ContentAiSelectionAsk` pill alongside
 *     the FAB.
 *   - `AiSuppressed`       — `isAssessmentLive` loses both AI trigger nodes.
 *   - `EnrollGated`        — the whole rail+children row is replaced by
 *     `EnrollGate`.
 */

/** Which `/learn/**` surface is currently active — drives whether a rail mounts. */
export type LearnSurface = "content" | "personalProject" | "leaderboard" | "other"

/** Surfaces whose real rail body (out of scope here, see file header) exists in the real app. */
const RAIL_SURFACES: ReadonlySet<LearnSurface> = new Set(["content", "leaderboard"])

/** Rail persistence + bounds — mirrors the real `learn/layout.tsx` rail's own defaults. */
const RAIL_STORAGE_KEY = "learn-shell-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 256
const RAIL_MAX_WIDTH = 480
const RAIL_ARIA_LABEL = "Drag to resize the side panel"
const RAIL_LOADING_LABEL = "Loading side panel"

/**
 * Fields `LearnShell` relays into `EnrollGate` — see the file header's
 * "`preview` IS A RELAYED SLOT" note for why `preview`/`price` ride along with
 * `title`/`description`, plus the `onEnroll` callback the gate needs to fire.
 */
export interface LearnShellEnrollGateProps
    extends Pick<EnrollGateProps, "title" | "description" | "preview" | "price"> {
    /** Fired when the learner takes the gate's enroll CTA. */
    onEnroll: () => void
}

/**
 * A resolved, already-positioned "ask AI about this selection" request — see
 * the file header for why `LearnShell` never tracks the selection itself.
 */
export interface LearnShellSelectionAsk {
    /** Viewport point to plant the pill at (already resolved by the caller). */
    anchor: ContentAiSelectionAskAnchor
    /** `true` → the pill carries the "New" badge. */
    isNew?: boolean
}

/** Props for {@link LearnShell}. */
export interface LearnShellProps {
    /** Which `/learn/**` surface is mounted right now — drives which rail body would mount. */
    activeSurface: LearnSurface
    /** `true` → the active surface requires enrollment the viewer does not have; replaces the whole body with `EnrollGate`. */
    isEnrollGated: boolean
    /** `true` → a timed/live assessment is running; suppresses BOTH AI triggers regardless of `isEnrollGated`. */
    isAssessmentLive: boolean
    /** `title`/`description`/`preview`/`price` relayed into `EnrollGate`, plus its `onEnroll`. Required only while `isEnrollGated`. */
    enrollGateProps?: LearnShellEnrollGateProps
    /** Fired when the floating AI trigger is pressed — the real layout opens the AI chat rail/drawer in response. */
    onOpenAiChat: () => void
    /** `true` → that chat surface is already open, so `ContentAiFab` hides instead of floating on top of it. */
    isAiChatOpen?: boolean
    /** The current text-selection ask request, already resolved+positioned by the caller. `null`/omitted → no selection to react to. */
    selectionAsk?: LearnShellSelectionAsk | null
    /** Fired when the selection-ask pill is pressed. */
    onOpenSelectionAsk: () => void
    /** The active route's own content — the one place `ReactNode` is valid above frame tier (§12). */
    children: ReactNode
}

/**
 * The `/learn/**` layout shell. See the file header for the full contract, the
 * scope gaps left deliberately open, and why `LeaderboardCategoryNav` was not
 * reused despite the inventory hint.
 *
 * @param props - {@link LearnShellProps}
 */
const LearnShell = ({
    activeSurface,
    isEnrollGated,
    isAssessmentLive,
    enrollGateProps,
    onOpenAiChat,
    isAiChatOpen = false,
    selectionAsk = null,
    onOpenSelectionAsk,
    children,
}: LearnShellProps) => {
    // A locked surface has nothing real to ask AI about yet, on top of the
    // brief's own `isAssessmentLive` suppression.
    const showAiTriggers = !isEnrollGated && !isAssessmentLive

    const railAndContent = [
        ...(RAIL_SURFACES.has(activeSurface) ? [() => (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={RAIL_ARIA_LABEL}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <StackV
                    gap={1}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center"
                    justify="center"
                    classNames={["h-full"]}

                    items={[() => <Spinner label={RAIL_LOADING_LABEL} />]}
                />
            </ResizableRail>
        )] : []),
        () => (
            <div className="min-w-0 flex-1">
                {children}
            </div>
        ),
    ]

    return (
        <div>
            {isEnrollGated && enrollGateProps != null ? (
                <EnrollGate
                    title={enrollGateProps.title}
                    description={enrollGateProps.description}
                    preview={enrollGateProps.preview}
                    price={enrollGateProps.price}
                    onEnroll={enrollGateProps.onEnroll}


                />
            ) : (
                <div className="min-h-[calc(100dvh-4rem)]">
                    <StackH
                        gap={1}
                        items={railAndContent}
                    />
                </div>
            )}

            {showAiTriggers ? (
                <>
                    <ContentAiFab
                        onOpen={onOpenAiChat}
                        isOpen={isAiChatOpen}


                    />
                    {selectionAsk != null ? (
                        <ContentAiSelectionAsk
                            onOpen={onOpenSelectionAsk}
                            anchor={selectionAsk.anchor}
                            isNew={selectionAsk.isNew}


                        />
                    ) : null}
                </>
            ) : null}
        </div>
    )
}

