import type { ReactNode } from "react"
import { Container } from "@sb-components/frames/Container/Container"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { ProfileHero, type ProfileHeroUser } from "@sb-components/starci/blocks/profile/ProfileHero/ProfileHero"
import { ProfileTabsBar, type ProfileTab } from "@sb-components/starci/blocks/navigation/ProfileTabsBar/ProfileTabsBar"
import { ProfileLoadingState } from "@sb-components/starci/blocks/profile/ProfileLoadingState/ProfileLoadingState"
import { ProfileNotFoundState } from "@sb-components/starci/blocks/profile/ProfileNotFoundState/ProfileNotFoundState"
import { ProfileLockedState } from "@sb-components/starci/blocks/profile/ProfileLockedState/ProfileLockedState"

/**
 * `PublicProfileLayout` — the wrapper mounted once per `/profile/[username]/**`
 * scope. Four structural leaves, in the "loading → not-found → locked →
 * content" branch order, each swapping the whole composed body:
 *   - `Loading`  — `ProfileLoadingState` alone.
 *   - `NotFound` — `ProfileNotFoundState` alone.
 *   - `Locked`   — `ProfileLockedState` alone (identity visible, tabs withheld).
 *   - `Content`  — `ProfileTabsBar` chrome above a two-column `ProfileHero` +
 *     route-panel body; owner-vs-visitor tab gating and the `canHire` CTA fork
 *     are data states within this leaf.
 */

/** Per-section tab visibility for a VISITOR (the owner always sees every tab) — feeds the `visibleTabs`/`hiddenTabs` computation below. */
export interface PublicProfileSectionVisibility {
    /** Show the "Projects" tab to visitors. */
    projects: boolean
    /** Show the "Challenges" tab to visitors. */
    challenges: boolean
    /** Show the "Skills" tab to visitors. */
    skills: boolean
    /** Show the "Activity" tab to visitors. */
    activity: boolean
}

/**
 * The full profile entity this layout branches on. Extends {@link ProfileHeroUser}
 * (see file header) with the three fields only THIS layout needs.
 */
export interface PublicProfileUser extends ProfileHeroUser {
    /** `true` → the owner has locked the profile. Only bites a VISITOR (`profileLocked && !isSelf`). */
    profileLocked?: boolean
    /** Absent = every section tab shows. */
    sectionVisibility?: PublicProfileSectionVisibility
    /** `true` → this person is open to hiring offers — half of the `canHire` gate (paired with `social.github`). */
    openToWork?: boolean
}

/** Fixed copy for the not-found branch — see file header for why this is not a prop. */
const NOT_FOUND_TITLE = "Profile not found"
const NOT_FOUND_DESCRIPTION = "This profile does not exist, has been removed, or the link is wrong."

/** Accessible name for the tab strip — layout-owned wording (§14d.1), `ProfileTabsBar` carries no i18n of its own. */
const PROFILE_TABS_ARIA_LABEL = "Public profile sections"

/** Every public-profile destination, in display order — ported from the real `PROFILE_TABS`. */
const PROFILE_TABS: ReadonlyArray<ProfileTab> = ["overview", "projects", "challenges", "skills", "cv", "activity"]

/** The section tabs gated by {@link PublicProfileSectionVisibility} (overview + cv are never gated this way). */
const SECTION_TABS: ReadonlyArray<ProfileTab> = ["projects", "challenges", "skills", "activity"]

/**
 * Which tabs to draw for THIS viewer, and (owner-only) which of those the owner
 * switched off for everyone else — ported from the real `ProfileTabsBar/index.tsx`'s
 * `visibleTabs`/`isSectionHidden`, now living here per the file header.
 */
const resolveProfileTabs = (
    user: PublicProfileUser,
    isSelf: boolean,
    hasPublicCv: boolean,
): { visibleTabs: ReadonlyArray<ProfileTab>, hiddenTabs: ReadonlyArray<ProfileTab> | undefined } => {
    const isSectionHidden = (tabId: ProfileTab): boolean =>
        !isSelf && SECTION_TABS.includes(tabId) && user.sectionVisibility?.[tabId as keyof PublicProfileSectionVisibility] === false
    const visibleTabs = PROFILE_TABS.filter((tabId) => {
        if (tabId === "cv") {
            return isSelf || hasPublicCv
        }
        return !isSectionHidden(tabId)
    })
    // the "· hidden" marker only makes sense for the OWNER's own view of a tab they hid from everyone else
    const hiddenTabs = isSelf
        ? SECTION_TABS.filter((tabId) => user.sectionVisibility?.[tabId as keyof PublicProfileSectionVisibility] === false)
        : undefined
    return { visibleTabs, hiddenTabs }
}

/** Props for {@link PublicProfileLayout}. */
export interface PublicProfileLayoutProps {
    /** `true` while the profile read is still in flight (first load). */
    isLoading: boolean
    /** The resolved profile, or `null` once the read has SETTLED with nothing found. */
    user: PublicProfileUser | null
    /** `true` → the route's username IS the signed-in viewer. */
    isSelf: boolean
    /** `true` → the viewed user has a PUBLIC cv — shows the "CV" tab to visitors too (feeds the tab-gating computation). */
    hasPublicCv: boolean
    /** Which profile tab is active right now (relayed to {@link ProfileTabsBar}). */
    activeTab: ProfileTab
    /** Fired with the tab the reader picked (relayed to {@link ProfileTabsBar}). */
    onTabChange: (tab: ProfileTab) => void
    /** `true` → the viewer already follows this user (relayed into {@link ProfileHero}). */
    following: boolean
    /** `true` → a follow/unfollow request is in flight (relayed into {@link ProfileHero}). */
    isFollowPending: boolean
    /** Fired when the follow/unfollow action is pressed (relayed into {@link ProfileHero}). */
    onToggleFollow: () => void
    /** Fired when the profile owner takes the "edit profile" action (relayed into {@link ProfileHero}'s `onEdit`). */
    onEditProfile: () => void
    /** Fired when a recruiter presses "Hire me" — only reachable when the computed `canHire` gate is on (relayed into {@link ProfileHero}'s `onHire`). See file header. */
    onHire: () => void
    /** Fired when the share action is pressed (relayed into {@link ProfileHero}'s `onShare`). See file header. */
    onShare: () => void
    /** Fired from the not-found branch's one way out. */
    onGoHome: () => void
    /** Fired from the locked branch's one way forward (browse courses instead). */
    onGoCourses: () => void
    /** The active tab's own panel — rendered by that tab's own route. Mandatory — RULE 12. */
    children: ReactNode
}

/**
 * The public-profile shell. See the file header for the four-branch switch, the
 * "registered as chrome" tab strip, and every judgement call. See
 * {@link PublicProfileLayoutProps} for the full contract.
 *
 * @param props - {@link PublicProfileLayoutProps}
 */
const PublicProfileLayout = ({
    isLoading,
    user,
    isSelf,
    hasPublicCv,
    activeTab,
    onTabChange,
    following,
    isFollowPending,
    onToggleFollow,
    onEditProfile,
    onHire,
    onShare,
    onGoHome,
    onGoCourses,
    children,
}: PublicProfileLayoutProps) => {
    if (isLoading) {
        return (
            <div>
                <ProfileLoadingState

                />
            </div>
        )
    }

    if (!user) {
        return (
            <div>
                <ProfileNotFoundState
                    title={NOT_FOUND_TITLE}
                    description={NOT_FOUND_DESCRIPTION}
                    onGoHome={onGoHome}

                />
            </div>
        )
    }

    // Locked profile viewed by a non-owner — mirrors the real `isLocked = Boolean(user?.profileLocked) && !isSelf`.
    if (user.profileLocked && !isSelf) {
        return (
            <div>
                <ProfileLockedState
                    user={user}
                    onGoCourses={onGoCourses}

                />
            </div>
        )
    }

    const { visibleTabs, hiddenTabs } = resolveProfileTabs(user, isSelf, hasPublicCv)
    // mirrors the real `PublicProfile`'s own `canHire` gate — see file header
    const canHire = !isSelf && Boolean(user.openToWork) && Boolean(user.social?.github)

    // aside + routed panel — the pair the identity/content two-column body composes
    const asideAndPanel = [
        () => (
            <aside className="w-full @app-md:w-72 @app-md:shrink-0">
                <ProfileHero
                    user={user}
                    isSelf={isSelf}
                    canHire={canHire}
                    following={following}
                    isFollowPending={isFollowPending}
                    onToggleFollow={onToggleFollow}
                    onHire={onHire}
                    onEdit={onEditProfile}
                    onShare={onShare}

                />
            </aside>
        ),
        () => (
            <main className="min-w-0 flex-1">
                {children}
            </main>
        ),
    ]

    // column-first, becomes a row from @app-md — same technique SettingsLayout uses for its own outer switch (see file header)
    const profileBody = (
        <div className="@app-md:flex-row @app-md:items-start">
            <StackV
                gap={7}
                items={asideAndPanel}
            />
        </div>
    )

    // chrome above the body — mirrors the real Navbar bottom-layer position; see file header
    const tabsAndBody = [
        () => (
            <ProfileTabsBar
                activeTab={activeTab}
                visibleTabs={visibleTabs}
                onTabChange={onTabChange}
                hiddenTabs={hiddenTabs}
                ariaLabel={PROFILE_TABS_ARIA_LABEL}

            />
        ),
        () => (
            <Container
                size="xl"
                padding={6}

                body={() => profileBody}
            />
        ),
    ]

    return (
        <div>
            <StackV
                gap={1}

                items={tabsAndBody}
            />
        </div>
    )
}

export { PublicProfileLayout }

import React from "react"
import { CourseContents } from "./CourseContents"
import { BlockAnatomy, type AnatomyNode } from "@sb-utils/BlockAnatomy/BlockAnatomy"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * Shared anatomy parts + a per-device·per-state leaf renderer for the
 * `Screens/CourseContents/<Device>/<State>` stories. NOT a story file (leading
 * `_` keeps it out of the `*.stories` glob) — device story files import from here
 * so the parts + framing live in ONE place.
 */

/**
 * EVERY node this screen can show, in ONE list — 11 entries: 4 frames, 3 blocks, and 4
 * composites (incl. the empty-state frame). Mirrors the real `_CourseContents` spine.
 *
 * There is deliberately NO per-state variant of this list. The panel derives the tree from
 * the DOM and uses this table only as a whitelist, so a node that is not rendered cannot
 * reach the tree even when it is declared here. The previous `partsFor(isEmpty, viewer)`
 * was therefore a THIRD place deciding presence — after the screen's own `? null` and each
 * block's self-hide — and it is what produced a tree that disagreed with the render: it
 * filtered `CourseTeamGate` out for paid viewers while the block's own condition
 * (`!isEnrolled || isInTeam`) keeps it VISIBLE for a paid viewer who is not in the team.
 * One list cannot drift from the render; a filtered copy always can.
 */
export const PARTS: Array<AnatomyNode> = [
    // A FRAME is a DEP too, and the tree recurses into its children: `Container`
    // (reading width + page padding) and `StackV` (rhythm between blocks) decide the
    // entire page frame, so the screen tree lists them, not just blocks.
    {
        name: "Container",
        tier: "frame",
        role: "reading width + page padding — `size=\"md\"` for a text column; `padding` is pinned to the §10 scale",
        storyId: "frames-container-container--default",
    },
    {
        // Different name from the `StackV` inside it: the panel groups nodes BY NAME, so a matching name would merge them into one.
        name: "StackV",
        tier: "frame",
        role: "rhythm between two REGIONS — `gap=\"page\"` separates the course-identity cluster from the content (§10: sections-wide)",
        storyId: "frames-stack-stackv--default",
    },
    {
        name: "StackV",
        tier: "frame",
        role: "VERTICAL rhythm between blocks — one seam, one owner (§10a)",
        storyId: "frames-stack-stackv--default",
    },
    {
        name: "StackH",
        tier: "frame",
        role: "horizontal row — the continue cluster (title <-> Resume) and each lesson row's meta cluster",
        storyId: "frames-stack-stackh--default",
    },
    {
        // §11a — SCREEN tier, only the HIGHEST node: the screen composes PageHeader directly
        // (mirrors the real `_CourseContents`). Breadcrumbs + HighlightChip meta are internal
        // to it → drill in PageHeader's own story, not here.
        name: "PageHeader",
        tier: "composite",
        role: "course identity — breadcrumb + title + description + catalog-meta chips",
        storyId: "composites-layout-page-pageheader--full",
    },
    // WARNING: the node name must match EXACTLY the `data-anat-part` the component emits:
    // the DOM emits `CourseTeamGate`, not `Callout` (that's the FRAME the block
    // uses internally). Declaring the wrong name ⇒ the node never makes it into the
    // tree. The tier would be wrong too: `composite` while `storyId` points to a BLOCK.
    //
    // The gate hides itself on ITS OWN data (`!isEnrolled || isInTeam`), which for a PAID
    // viewer who is not yet in the team means it STAYS. Do not describe it as "hidden once
    // purchased" — measured on the paid render, it is in the DOM.
    { name: "CourseTeamGate", tier: "block", role: "GitHub-team warning — shows for an enrolled viewer who is not in the team yet", state: "warning", storyId: "starci-blocks-learn-courseteamgate-courseteamgate--warning" },
    // The link must point at the leaf this screen ACTUALLY renders. It used to point at
    // `--price-loading`, so clicking a dep on a fully loaded screen landed on the shimmer
    // leaf. A story-id gate can only prove an id EXISTS; that it points at the right leaf
    // is a reader's job (`scripts/check-story-ids.mjs` deliberately says so).
    { name: "TrialConversionStrip", tier: "block", role: "trial→enroll conversion strip; the screen drops it entirely once purchased", storyId: "starci-blocks-commerce-trialconversionstrip-trialconversionstrip--default" },
    { name: "ProgressMeter", tier: "composite", role: "the continue cluster's honest unified completion meter (lessons + challenges in one bar)", storyId: "composites-stats-progressmeter--label-and-value" },
    { name: "LearnNudges", tier: "block", role: "what to do today — cards due · mock interview · rank. The screen passes `kind` (ENUM); the block picks the icon (§14b)", storyId: "starci-blocks-learn-learnnudges-learnnudges--nudges" },
    { name: "SurfaceCardList", tier: "composite", role: "keep-going path — the current module's lessons as rows: state icon · title · reading time · difficulty chip · lock", storyId: "composites-cards-surfacecard-surfacecardlist--default" },
    // The empty state replaces the whole spine with this frame. It lives in the SAME list:
    // on a content render it simply is not in the DOM, so it cannot reach the tree.
    { name: "AsyncContentEmpty", tier: "composite", role: "the course has no contents yet — icon + title + description", storyId: "composites-async-asynccontent-asynccontentempty--basic" },
]

/** Args for {@link deviceLeaf}. */
export interface DeviceLeafArgs {
    /** Fixed container width (px) → the layout re-lays-out to it via `@app-*`. Omit = full (desktop). */
    width?: number
    /** `true` → renders the whole screen in the RESTING state (the flag flows down into each block). */
    isSkeleton?: boolean
    /** `true` → the course has no lessons yet. */
    isEmpty?: boolean
    /** Content viewer (only meaningful when NOT empty). */
    viewer?: "trial" | "paid"
    /** Story display name = leaf label (e.g. "Default", "Loading"). */
    leaf: string
    /** Optional rationale line. */
    reason?: React.ReactNode
}

/**
 * The Code tab's snippet for one leaf — EVERY leaf carries `code`: a screen owes
 * the same two tabs as an atom does.
 *
 * The snippet is built from the very args that produced the render, so it can never drift
 * from what is on screen — hand-writing one snippet per device × state would
 * have gone stale on the first prop rename.
 */
const leafCode = ({ width, isSkeleton, isEmpty, viewer }: Required<Pick<DeviceLeafArgs, "isSkeleton" | "isEmpty" | "viewer">> & { width?: number }) => {
    const props = [
        `viewer="${viewer}"`,
        ...(isSkeleton ? ["isSkeleton"] : []),
        ...(isEmpty ? ["isEmpty"] : []),
    ]
    const call = `<CourseContents ${props.join(" ")} />`
    // The device frame is part of the STORY, not of the screen — show it so a reader
    // knows the width comes from an `@container`, not from the screen itself.
    return width == null
        ? call
        : `<div className="@container" style={{ width: ${width} }}>
    ${call}
</div>`
}

/**
 * Render ONE CourseContents leaf: BlockAnatomy (anatomy is everywhere) wrapping the
 * layout inside its OWN `@container` at the device width, in the given state.
 */
export const deviceLeaf = ({ width, isSkeleton = false, isEmpty = false, viewer = "trial", leaf, reason }: DeviceLeafArgs) => (
    <StackV
        gap={1}
        padding={6}
        principle="page-pad"
        explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
        body={() => (
            <BlockAnatomy
                name="CourseContents"
                // `screen`, NOT `block`.
                tier="screen"
                leaf={leaf}
                parts={PARTS}
                reason={reason}
                code={leafCode({ width, isSkeleton, isEmpty, viewer })}
            >
                <div
                    className="@container overflow-hidden rounded-none border border-dashed border-accent"
                    style={width ? { width, maxWidth: "100%" } : undefined}
                >
                    <CourseContents viewer={viewer} isSkeleton={isSkeleton} isEmpty={isEmpty} />
                </div>
            </BlockAnatomy>
        )}
    />
)

import React from "react"
import { MapTrifoldIcon, ShareNetworkIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@sb-components/starci/blocks/learn/MindMapRail/MindMapRail"
import { MindMapContinueButton } from "@sb-components/starci/blocks/learn/MindMapContinueButton/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@sb-components/starci/blocks/learn/MindMapFullscreenButton/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@sb-components/composites/stats/Legend/Legend"
import { AsyncContentEmpty } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * SCREEN — `MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list, the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose), and why the canvas
 * region is a documented §B3 gap rather than a faked ReactFlow mount.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean
}

/** localStorage key + bounds the real `MindMapWorkspace` persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

const CANVAS_GAP_TITLE = "Concept map region"
const CANVAS_GAP_DESCRIPTION = "The real ReactFlow graph (nodes, drawer, minimap) isn't built this pass — this block is where it will mount (§B3)."
const CANVAS_GAP_LOADING_TITLE = "Loading map…"

const WORKSPACE_EMPTY_TITLE = "This course has no concept map yet"
const WORKSPACE_EMPTY_DESCRIPTION = "The map is generated automatically once the course has enough modules — check back later."

/** Props for the {@link MindMapCanvasGap} stand-in below. */
interface MindMapCanvasGapProps {
    isLoading?: boolean
}

/**
 * Stand-in for the out-of-reach ReactFlow engine (§B3) — see the file header's
 * "CANVAS GAP" note for why `AsyncContentEmpty` is the reused shape here.
 */
const MindMapCanvasGap = ({ isLoading = false}: MindMapCanvasGapProps) => (
    <StackV
        gap={1}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        align="center"
        justify="center"
        classNames={["h-full"]}

        items={[() => (
            <AsyncContentEmpty

                icon={ShareNetworkIcon}
                title={isLoading ? CANVAS_GAP_LOADING_TITLE : CANVAS_GAP_TITLE}
                description={isLoading ? undefined : CANVAS_GAP_DESCRIPTION}
            />
        )]}
    />
)

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case.
 */
const MindMapWorkspaceEmpty = () => (
    <div className="h-[calc(100dvh-4rem)]">
        <StackV
            gap={1}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            justify="center"
            items={[() => (
                <AsyncContentEmpty

                    icon={MapTrifoldIcon}
                    title={WORKSPACE_EMPTY_TITLE}
                    description={WORKSPACE_EMPTY_DESCRIPTION}
                />
            )]}
        />
    </div>
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
}: MindMapPageProps) => {
    if (variant === "workspace" && isEmpty) {
        return <MindMapWorkspaceEmpty />
    }

    const railSection = (
        <MindMapRail

            query={query}
            onQuery={onQuery}
            tier={tier}
            onTier={onTier}
            items={items}
            selectedId={selectedId}
            onPick={onPick}
            isLoading={isRailLoading}
            ariaLabel={railAriaLabel}
            tierAriaLabel={railTierAriaLabel}
            isSkeleton={isSkeleton}

        />
    )

    // The canvas region's floating chrome — in the real app these render as the
    // SAME ReactFlow engine's own Panel children, see the file header's
    // "OVERLAYS ARE FRAMES" note.
    const showOverlays = variant === "standalone" && !isSkeleton

    const canvasItems = [
        () => <MindMapCanvasGap isLoading={isSkeleton} />,
        ...(showOverlays ? [
            () => (
                <div className="absolute inset-x-0 top-4 z-10">
                    <StackV
                        gap={1}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <MindMapContinueButton
                                resumeHref={resumeHref}
                                allContentDone={allContentDone}
                                onResume={onResume}
                                continueAriaLabel={continueAriaLabel}
                                isSkeleton={isSkeleton}
                            />
                        )]}
                    />
                </div>
            ),
            () => (
                <div className="absolute bottom-4 left-4 z-10">
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <div>
                                <Legend items={legendItems} />
                            </div>
                        )]}
                    />
                </div>
            ),
            () => (
                <div className="absolute bottom-4 right-4 z-10">
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <MindMapFullscreenButton
                                onZoomIn={onZoomIn}
                                onZoomOut={onZoomOut}
                                onToggleFullscreen={onToggleFullscreen}
                                isFullscreen={isFullscreen}
                                ariaLabels={fullscreenAriaLabels}
                                isSkeleton={isSkeleton}
                            />
                        )]}
                    />
                </div>
            ),
        ] : []),
    ]

    const workspaceRail = (
        <ResizableRail
            storageKey={RAIL_STORAGE_KEY}
            defaultWidth={RAIL_DEFAULT_WIDTH}
            minWidth={RAIL_MIN_WIDTH}
            maxWidth={RAIL_MAX_WIDTH}
            ariaLabel={railResizeAriaLabel}
            // eslint-disable-next-line starci-fe/handler-on-prefix -- `handleSide` is a ResizableRail layout prop (which edge the resize handle sits on), a noun not an onXxx event handler
            handleSide="right"
            className="h-full shrink-0 border-r border-default"
        >
            <div className="overflow-y-auto">
                <StackV
                    padding={6}
                    principle="page-pad"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                    gap={1}
                    classNames={["h-full"]}
                    isSkeleton={isSkeleton}
                    items={[() => railSection]}
                />
            </div>
        </ResizableRail>
    )

    return (
        <div className="h-[calc(100dvh-4rem)]">
            <StackH
                gap={1}
                isSkeleton={isSkeleton}
                items={[
                    ...(variant === "workspace" ? [() => workspaceRail] : []),
                    // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
                    // floating chrome that in the real app renders as the SAME engine's own Panel
                    // children — see the file header's "OVERLAYS ARE FRAMES" note.
                    () => (
                        <div className="relative min-w-0 flex-1">
                            <StackV
                                gap={1}
                                isSkeleton={isSkeleton}
                                items={canvasItems}
                            />
                        </div>
                    ),
                ]}
            />
        </div>
    )
}

