import React from "react"
import { WorkSessionHeader } from "@sb-components/starci/blocks/navigation/WorkSessionHeader/WorkSessionHeader"
import {
    PlaygroundStepGuide,
    type PlaygroundStep,
    type PlaygroundStepVerifyState,
} from "@sb-components/starci/blocks/learn/PlaygroundStepGuide/PlaygroundStepGuide"
import {
    PlaygroundResourcePanel,
    type PlaygroundResourceEntry,
    type PlaygroundConnectionState as PlaygroundResourcePanelConnection,
} from "@sb-components/starci/blocks/learn/PlaygroundResourcePanel/PlaygroundResourcePanel"
import {
    PlaygroundConnectSheet,
    type PlaygroundConnectionState,
    type PlaygroundDeviceSpec,
    type PlaygroundAgentLogLine,
} from "@sb-components/starci/blocks/learn/PlaygroundConnectSheet/PlaygroundConnectSheet"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * SCREEN — `PlaygroundSessionPage`: run one playground exercise. See the
 * component's file header for the full function list and the two-pane layout's
 * precedent; this file only builds on top of that.
 *
 * ONE LEAF, THREE DATA STATES (§14d.2/§11f) — every state renders the SAME four
 * blocks in the SAME two-pane-plus-docked-sheet shape; only what each block is
 * told changes (a step vs. no step left, a live pairing vs. a first-time wait).
 * None of the three removes or adds a node at the SCREEN's own tier — the
 * structural forks that exist (the guide's completion leaf, the sheet's device
 * body) already live one tier down, inside `PlaygroundStepGuide` and
 * `PlaygroundConnectSheet`'s own leaf/state splits.
 */

/** Props for {@link PlaygroundSessionPage}. */
export interface PlaygroundSessionPageProps {
    // ── session band (`WorkSessionHeader`) ──
    /** Back-link label — leave, run stays resumable. */
    backLabel: string
    /** Fired when the learner leaves without ending the run. */
    onBack: () => void
    /** Session title, e.g. the exercise name. */
    title?: string
    /** Where the learner is, already worded, e.g. "Step 2 / 5". */
    counter: string
    /** How many steps this run has. */
    total: number
    /** Which step is being viewed, 1-based. */
    current: number
    /** Steps already verified, 1-based. */
    doneSteps?: Array<number>
    /** Fired with a 1-based step when the learner taps the rail. */
    onStepPress?: (step: number) => void
    /** Finish-now label. Present with `onFinish` → the end-now control shows. */
    finishLabel?: string
    /** Fired when the learner ends the run early. */
    onFinish?: () => void

    // ── left pane: the step guide ──
    /** The step being read. Omit → every step is done, the guide shows its completion leaf. */
    step?: PlaygroundStep
    /** Where the current step's verify action stands. Ignored once `step` is omitted. */
    verifyState: PlaygroundStepVerifyState
    /** Fired when the learner presses `Verify` (or retries after a miss). */
    onVerify: () => void
    /** Fired from the guide's completion leaf, back to the Playground hub. */
    onLeaveGuideComplete: () => void

    // ── shared pairing state (right pane + docked sheet) ──
    /** How the paired machine's connection currently stands. */
    connection: PlaygroundConnectionState
    /** Round-trip time to the local agent. Only read while `connection === "connected"`. */
    latencyMs?: number
    /** The paired machine's specs, once the agent has reported at least once. */
    device?: PlaygroundDeviceSpec
    /** Live tail of the local agent's log, oldest first. */
    agentLog: Array<PlaygroundAgentLogLine>
    /** Fired when the learner presses the sheet's reconnect action. */
    onReconnect: () => void

    // ── right pane: the live resource snapshot ──
    /** The flat resource snapshot as the socket reports it. */
    resources: Array<PlaygroundResourceEntry>

    // ── docked sheet open state ──
    /** Whether the connect sheet's body (device specs + log) is expanded. Controlled. */
    isConnectSheetOpen: boolean
    /** Fired with the next expanded state when the learner presses the sheet's toggle. */
    onConnectSheetOpenChange: (open: boolean) => void

}

/**
 * The playground run screen. See the file header for the function list and the
 * two-pane layout's precedent.
 *
 * @param props - {@link PlaygroundSessionPageProps}
 */
const PlaygroundSessionPage = ({
    backLabel,
    onBack,
    title,
    counter,
    total,
    current,
    doneSteps,
    onStepPress,
    finishLabel,
    onFinish,
    step,
    verifyState,
    onVerify,
    onLeaveGuideComplete,
    connection,
    latencyMs,
    device,
    agentLog,
    onReconnect,
    resources,
    isConnectSheetOpen,
    onConnectSheetOpenChange,
}: PlaygroundSessionPageProps) => {
    // See the file header's "ONE CONNECTION ENUM, TWO VOCABULARIES" note — the
    // resource panel only ever asks a binary question.
    const resourcePanelConnection: PlaygroundResourcePanelConnection =
        connection === "connected" ? "connected" : "notConnected"

    const guidePane = (
        <div className="overflow-y-auto">
            <StackV
                gap={1}
                padding={6}
                principle="page-pad"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                classNames={["min-w-0", "flex-1"]}

                items={[
                    () => (
                        <PlaygroundStepGuide

                            step={step}
                            verifyState={verifyState}
                            onVerify={onVerify}
                            onLeaveComplete={onLeaveGuideComplete}

                        />
                    ),
                ]}
            />
        </div>
    )

    const resourcePane = (
        <div className="overflow-y-auto @app-xl:w-[24rem]">
            <StackV
                gap={1}
                padding={6}
                principle="page-pad"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                classNames={["w-full", "shrink-0"]}

                items={[
                    () => (
                        <PlaygroundResourcePanel

                            connection={resourcePanelConnection}
                            resources={resources}

                        />
                    ),
                ]}
            />
        </div>
    )

    // The workspace region: two panes side by side, plus the docked sheet
    // anchored (not laid out) against this box — see the file header.
    return (
        <div className="h-[calc(100vh-4rem)]">
            <StackV
                gap={1}
                items={[
                    () => (
                        <WorkSessionHeader

                            backLabel={backLabel}
                            onBack={onBack}
                            title={title}
                            counter={counter}
                            total={total}
                            current={current}
                            doneSteps={doneSteps}
                            onStepPress={onStepPress}
                            finishLabel={finishLabel}
                            onFinish={onFinish}

                        />
                    ),
                    () => (
                        <div className="relative">
                            <StackV
                                gap={1}
                                classNames={["min-h-0", "flex-1"]}

                                items={[
                                    () => (
                                        <div className="overflow-hidden">
                                            <StackH
                                                principle="block-boundary"
                                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                                divider
                                                items={[
                                                    () => guidePane,
                                                    () => resourcePane,
                                                ]}
                                            />
                                        </div>
                                    ),
                                    () => (
                                        <div className="absolute inset-x-0 bottom-0 z-10">
                                            <StackV
                                                gap={1}

                                                items={[
                                                    () => (
                                                        <PlaygroundConnectSheet

                                                            connection={connection}
                                                            latencyMs={latencyMs}
                                                            device={device}
                                                            agentLog={agentLog}
                                                            onReconnect={onReconnect}
                                                            open={isConnectSheetOpen}
                                                            onOpenChange={onConnectSheetOpenChange}

                                                        />
                                                    ),
                                                ]}
                                            />
                                        </div>
                                    ),
                                ]}
                            />
                        </div>
                    ),
                ]}
            />
        </div>
    )
}

export { PlaygroundSessionPage }

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * Props for the {@link PressableCard} block.
 *
 * TIER NOTE: this folder sits under `blocks/cards`, but the component itself
 * owns no domain entity — every prop here is a shape (`children`, `onPress`,
 * `href`, `actions`) never a field of something fetched. That is BLOCK-7's
 * detection signal: it is really a **composite** mis-filed in a block folder.
 * Left in place (moving the folder breaks every importer below), but treated
 * as a composite for this pass — one file, `cn()` allowed (COMPOSITE-5), and
 * `className` kept as a raw string rather than `classNames: Array<AllowedClassName>`
 * because three real callers outside this folder (`GroupPressableCard`,
 * `SummaryCard`, `ConsultantCard`) already forward arbitrary skin classes
 * (radius/border/hover overrides) through it — narrowing the type here would
 * break them without touching a single one of their files.
 *
 * `composites/cards/SurfaceCard` (`SurfaceCard`, exported off `Base`) is the
 * emerging canonical member for this exact job — same whole-card press target,
 * same stretched-link `actions` pattern, plus ripple/selection/verdict-band —
 * and its own header explicitly notes it folds in "was `PressableCard`". It is
 * NOT swapped in here: its hover/ripple treatment differs from this file's
 * (tint-on-hover, no ripple), so delegating to it would change the rendered
 * look for the three live callers above, not just the code shape. Consolidating
 * onto `SurfaceCard` is a separate migration (each caller needs the `children`
 * → `body` slot conversion too), left as debt rather than folded in silently.
 */
export interface PressableCardProps extends WithClassNames<undefined> {
    /** Card body — composed freely by the caller (icon tiles, text, chips…). */
    children: React.ReactNode
    /**
     * Press handler for an action card (select / toggle). Ignored when
     * {@link PressableCardProps.href} is set. One of `onPress` / `href` should
     * be provided for the card to be interactive.
     */
    onPress?: () => void
    /** Navigation target — renders the card as an anchor when provided. */
    href?: string
    /** Disables interaction and dims the card (action cards only). */
    isDisabled?: boolean
    /**
     * Secondary interactive controls (buttons / menus) that live INSIDE the card
     * but act INDEPENDENTLY of the whole-card press — e.g. a "Continue" button +
     * an overflow menu on a course-progress card.
     *
     * Providing this switches the card to the accessible **stretched-link**
     * pattern (Inclusive Components / Adrian Roselli): the whole-card target
     * becomes a TRANSPARENT overlay that covers the card, and these actions sit
     * ABOVE it (later in source order + `z-10`) so each stays separately
     * clickable. This is the correct alternative to illegally nesting a
     * `<button>` inside the card's own `<button>`/`<a>` — which is invalid HTML,
     * breaks the keyboard/AT focus order, AND is what made the card grow tall
     * (a block button laying its interactive children out on their own lines).
     *
     * REQUIRES {@link PressableCardProps.label} — the overlay target no longer
     * wraps the children text, so it needs its own accessible name.
     */
    actions?: ComponentType
    /**
     * Accessible name for the whole-card press target. REQUIRED when
     * {@link PressableCardProps.actions} is set (the stretched overlay covers the
     * card but has no visible text of its own, so it must carry an `aria-label`).
     * Optional otherwise — without `actions` the children ARE the card's
     * accessible name, so pass this only when they carry no readable text (an
     * icon-only tile). Keep it descriptive of the destination/action ("Open the
     * Fullstack Mastery track"), never generic ("click here").
     */
    label?: string
    /**
     * Caller identity to wear on this card's root instead of its own — pass this
     * when a sentence-tier component roots on this card (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * A whole-card press target with the default surface card look (surface fill,
 * concentric `rounded-3xl`, fixed `px-4 py-3` padding, `shadow-surface`
 * elevation AT REST — per `card.md` §0, a top-level bounded card, so it must
 * read as a card even before hover) plus a hover affordance and keyboard
 * focus ring. Exists because HeroUI v3 `Card` is a
 * non-interactive `<div>` — this component owns the card styling on a real
 * `<button>` / `<a>` so features can compose a clickable card without
 * hand-rolling styles (per the no-style-in-features rule). Use for navigation
 * tiles, selectable option cards, and bookmark rows.
 *
 * When the card also needs its OWN buttons (a "Continue" CTA, an overflow menu),
 * pass them via {@link PressableCardProps.actions} + {@link PressableCardProps.label}:
 * the card renders as the accessible stretched-link pattern (a transparent
 * whole-card overlay UNDER the actions) instead of nesting interactive elements
 * — see the `actions` prop docs.
 *
 * @param props - {@link PressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/PressableCard/PressableCard.stories
 */
export const PressableCard = ({
    children,
    onPress,
    href,
    isDisabled = false,
    actions: Actions,
    label,
    className,
    identity,
}: PressableCardProps) => {
    // Shared card surface + disabled dim, identical across both render paths so
    // a card reads the same with or without actions. `shadow-surface` is a
    // top-level bounded card (card.md §0 elevation convention) — it must read as
    // one at rest, not only once the pointer arrives (teacher: "render it as a card").
    // One hover treatment only (tint) — no lift variant, no press-scale.
    const surface = cn(
        "rounded-3xl bg-surface px-4 py-3 text-left shadow-surface transition-colors hover:bg-surface-secondary",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "PressableCard" })

    // ── Simple whole-card target (no secondary actions) — the common case;
    // the whole card is ONE <button>/<a> and its children are its label. ──────
    if (!Actions) {
        const base = cn(
            "block w-full outline-none focus-visible:ring-2 focus-visible:ring-accent",
            surface,
        )
        if (href && !isDisabled) {
            return (
                <a href={href} aria-label={label} className={base} {...identityAttrs}>
                    {children}
                </a>
            )
        }
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                aria-label={label}
                className={cn(base, !isDisabled && "cursor-pointer")}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }

    // ── Card WITH its own buttons — stretched-link pattern. The card is a plain
    // relative <div>; a transparent overlay <a>/<button> covers it (whole-card
    // press), and the actions sit ABOVE the overlay so they stay clickable. No
    // interactive element is ever nested inside another. Row built with `StackH`
    // (frame tier) instead of a hand-rolled `flex items-center gap-3` wrapper —
    // same shape as `composites/cards/SurfaceCard`'s own actions branch. ───────
    const overlay = cn(
        // covers the whole card; the focus ring reads as a card-level ring since
        // the overlay's border-box IS the card's bounds
        "absolute inset-0 rounded-3xl outline-none focus-visible:ring-2 focus-visible:ring-accent",
        isDisabled ? "cursor-not-allowed" : "cursor-pointer",
    )
    return (
        <div className={cn("relative w-full", surface)} {...identityAttrs}>
            <StackH
                gap={4}
                items={[
                    () => <div className="min-w-0 flex-1">{children}</div>,
                    () => (
                        <div className="relative z-10">
                            <StackH gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." classNames={["shrink-0"]} items={[() => <Actions />]} />
                        </div>
                    ),
                ]}
            />
            {href && !isDisabled ? (
                <a href={href} aria-label={label} className={overlay} />
            ) : (
                <button
                    type="button"
                    onClick={onPress}
                    disabled={isDisabled}
                    aria-label={label}
                    className={overlay}
                />
            )}
        </div>
    )
}

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Image } from "@/components/atoms/media/Image"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackV } from "@/components/frames/Stack"

/**
 * `FoundationCategoryList` — the Foundations content library's browse-and-drill-in
 * list: joined rows with a thumbnail, title, one-line description and a trailing
 * caret, plus a pager once there is more than one page. Loading swaps row content
 * to shimmer; the `Empty` state replaces the rows with an `EmptyState` (worded by
 * whether a search query drove the empty result), both bounded inside the same
 * `SurfaceCardList` surface.
 */

/** One category row — plain data; the block resolves the thumbnail chain and builds the wording. */
export interface FoundationCategoryListItem {
    /** Stable id — also what `onSelectCategory` fires with. */
    id: string
    /** Category title. */
    title: string
    /** One-line summary, shown as the row's subtitle. */
    description?: string
    /** Underlying tech/brand mark — rides as the `Image` atom's `fallbackSrc` (see file header). */
    logoSrc?: string
    /** Dedicated category thumbnail — wins over `logoSrc` when present (see file header). */
    thumbnailUrl?: string
}

/** Page state for the list's own pager — omit entirely when the caller has only one page. */
export interface FoundationCategoryListPagination {
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the reader picked. */
    onPageChange: (pageNumber: number) => void
}

/** Props for {@link FoundationCategoryList}. */
export interface FoundationCategoryListProps {
    /** The current page's categories, in display order. */
    categories: Array<FoundationCategoryListItem>
    /**
     * Current search text driving which empty reason applies when `categories`
     * is empty (see file header, judgement 2). Not rendered as a field by this
     * block — the search input itself is `FoundationCategorySearchBar`'s job.
     */
    searchQuery?: string
    /** Fired with a category's id on ANY row press. */
    onSelectCategory: (id: string) => void
    /** Page nav state. Omit → no pager, even with a full page of rows. */
    pagination?: FoundationCategoryListPagination
    /**
     * `true` → the list draws its own row mirror. `categories` empty while
     * loading (§12c) → guesses 3 rows, this composite's siblings' SSOT convention.
     */
    isSkeleton?: boolean
}

/** The library-itself-is-empty title — no search was involved, so no "try another word" hint applies. Ported verbatim from `foundations.emptyCategories`. */
const LIBRARY_EMPTY_TITLE = "No Foundations topics yet."

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler or a thumbnail. */
const SKELETON_CATEGORIES: Array<FoundationCategoryListItem> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
}))

/**
 * Resolves the thumbnail-priority chain (see file header, judgement 1) into the
 * `Image` atom's own `src`/`fallbackSrc` pair — a naming decision, not a second
 * rendering path.
 */
const resolveThumbnail = (category: FoundationCategoryListItem): { src?: string; fallbackSrc?: string } =>
    category.logoSrc
        ? { src: category.logoSrc, fallbackSrc: category.thumbnailUrl }
        : { src: category.thumbnailUrl, fallbackSrc: undefined }

const NoCategoriesEmptyState = ({ hasQuery, searchQuery }: { hasQuery: boolean; searchQuery?: string }) => (
    <EmptyState
        icon={hasQuery ? MagnifyingGlassIcon : undefined}
        title={hasQuery ? `No topics match "${searchQuery?.trim()}".` : LIBRARY_EMPTY_TITLE}
    />
)

/**
 * The Foundations library's browse-and-drill-in list. See the file header for
 * the thumbnail-priority chain, the two empty reasons, and why loading stays a
 * state of the same leaf rather than earning its own.
 *
 * @param props - {@link FoundationCategoryListProps}
 */
const FoundationCategoryList = ({
    categories,
    searchQuery,
    onSelectCategory,
    pagination,
    isSkeleton = false,
}: FoundationCategoryListProps) => {
    // Empty while loading (no real categories yet) → guess 3 rows, keeping the
    // right shape for when real data lands (§8). Once real `categories` exist,
    // keep the EXACT row count already there.
    const usingPlaceholders = isSkeleton && categories.length === 0
    const source = usingPlaceholders ? SKELETON_CATEGORIES : categories

    const rows: Array<SurfaceCardListItem> = source.map((category) => {
        const { src, fallbackSrc } = resolveThumbnail(category)
        return {
            key: category.id,
            leading: () => (
                <div className="size-10 shrink-0">
                    <Image
                        src={src}
                        fallbackSrc={fallbackSrc}
                        alt={category.title}
                        ratio="square"
                        radius="md"
                        isSkeleton={isSkeleton}

                    />
                </div>
            ),
            title: category.title,
            subtitle: category.description,
            // Every real row navigates — a constant of this domain, never conditional
            // (see file header, judgement 3).
            trailingIcon: CaretRightIcon,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectCategory(category.id),
        }
    })

    // Which of the two empty reasons applies (see file header, judgement 2) —
    // never during the skeleton branch, where "empty" just means "not loaded yet".
    const hasQuery = (searchQuery?.trim().length ?? 0) > 0
    const emptyState = !isSkeleton && categories.length === 0
        ? () => <NoCategoriesEmptyState hasQuery={hasQuery} searchQuery={searchQuery} />
        : undefined

    // Nothing to page through during the first fetch or an empty result (see
    // file header, judgement on the pager).
    const showPager = !isSkeleton && categories.length > 0 && pagination != null

    return (
        <StackV identity={{ tier: "block", component: "FoundationCategoryList" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <SurfaceCardList

                        isSkeleton={isSkeleton}
                        items={rows}
                        emptyState={emptyState}
                    />
                ),
                ...(showPager
                    ? [
                        () => (
                            <div>
                                <Pagination
