"use client"

import React from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { PostRow } from "@/components/blocks/blog/PostRow"
import { StackV } from "@/components/frames/Stack"
import { queryBlogPosts } from "@/modules/api/graphql/queries/query-blog-posts"
import { BlogCategory } from "@/modules/api/graphql/queries/types/blog"

/** How many related posts to surface at most. */
const MAX_RELATED = 3

/** Props for {@link RelatedPosts}. */
export interface RelatedPostsProps {
    /** Pillar to pull related posts from (the current article's category). */
    category: BlogCategory
    /** Slug of the current article — excluded from the related list. */
    currentSlug: string
}

/**
 * "More in {pillar}" strip at the end of an article. Reuses the existing
 * `blogPosts(category)` query (no new backend) to keep readers in the same
 * editorial pillar. Self-hiding: renders nothing when there are no other posts.
 */
export const RelatedPosts = ({ category, currentSlug }: RelatedPostsProps) => {
    const t = useTranslations("blog")
    const locale = useLocale()

    const { data } = useSWR(
        ["blog-related", category, currentSlug],
        async () => {
            const response = await queryBlogPosts({
                request: { category, limit: MAX_RELATED + 1, offset: 0 },
            })
            return response.data?.blogPosts.data ?? []
        },
    )

    const related = (data ?? [])
        .filter((post) => post.slug !== currentSlug)
        .slice(0, MAX_RELATED)

    // self-hiding section — nothing to show when this is the only post in the pillar
    if (related.length === 0) {
        return null
    }

    const formatDate = (iso: string) =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    return (
        <section className="border-t border-default pt-6">
            <StackV
                gap={4}
                principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <h2 className="text-lg font-semibold text-foreground">
                            {t("relatedTitle", { category: t(`categories.${category}`) })}
                        </h2>
                    ),
                    ...related.map((post) => () => (
                        <PostRow
                            post={post}
                            formattedDate={formatDate(post.publishedAt)}
                        />
                    )),
                ]}
            />
        </section>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    CaretRightIcon,
} from "@phosphor-icons/react"
import Link from "next/link"
import {
    useLocale,
} from "next-intl"
import {
    UserAvatar,
} from "@/components/blocks/identity/UserAvatar"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserAchievementsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserAchievementsSwr"
import { rankInfo, resolveSeniorityRank } from "@/modules/utils/rank"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link ProfileMenuCard}. */
export type ProfileMenuCardProps = Record<string, never>
/**
 * The DashboardPage rail's identity row: a rank-ringed avatar + display name +
 * @handle on the left, with a trailing caret. The whole row is a link to the
 * public profile. No level, no XP number — the only status surfaced is the
 * seniority rank encoded by the thin (2px) avatar ring colour; beginner/unranked
 * uses the neutral `--border` token rather than the flat grey rank hue.
 *
 * Self-contained container: reads the viewer from redux and derives the
 * seniority rank from the earned-achievement wall via SWR (deduped with the
 * rest of the page). `"use client"` for the store selector.
 *
 * @param props - optional className merged onto the row.
 */
export const ProfileMenuCard = () => {
    const locale = useLocale()
    const user = useAppSelector((state) => state.user.user)
    const achievementsSwr = useQueryUserAchievementsSwr(user?.id ?? null)
    const achievements = achievementsSwr.data

    /**
     * Readable name next to the avatar: the chosen display name, else the handle
     * before "@" so a raw email is never surfaced.
     */
    const displayName = useMemo(
        () => {
            const explicit = user?.displayName?.trim()
            if (explicit) {
                return explicit
            }
            const base = user?.email ?? user?.username ?? ""
            return base.split("@")[0]
        },
        [
            user,
        ],
    )

    // overall seniority rank → the ring colour (breadth-gated highest tier)
    const info = useMemo(
        () => {
            const earnedTiers = (achievements ?? [])
                .filter((item) => item.earned)
                .map((item) => item.tierReached ?? 1)
            return rankInfo(resolveSeniorityRank(earnedTiers))
        },
        [
            achievements,
        ],
    )

    // Ring colour: real seniority hue (junior=bronze · middle=silver · senior=gold). beginner/unranked reads as a
    // neutral grey (#8C95A1) → use the `--border` token so it's theme-clean, not a hardcoded grey.
    const ringColor = info.ring && info.rank !== "beginner" ? info.ring : "var(--border)"

    if (!user) {
        return null
    }

    return (
        <Link
            href={pathConfig().locale(locale).profile(user.username).build()}
            className={"group flex cursor-pointer items-center justify-between gap-3 no-underline transition-opacity hover:opacity-80"}
        >
            {/* avatar + name = left cluster; caret pinned right by justify-between */}
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                classNames={["min-w-0"]}
                items={[
                    () => (
                        // avatar with a thin 2px seniority ring — beginner/unranked → neutral `--border` token
                        <div
                            className="shrink-0 rounded-full ring-2"
                            style={{ "--tw-ring-color": ringColor } as React.CSSProperties}
                        >
                            <UserAvatar
                                className="size-10"
                                username={displayName}
                                avatar={user.avatar}
                                seed={user.username}
                            />
                        </div>
                    ),
                    () => (
                        <StackV
                            gap={1}
                            principle="name-handle"
                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                            classNames={["min-w-0"]}
                            items={[
                                () => (
                                    <span className="truncate text-sm font-semibold text-foreground">
                                        {displayName}
                                    </span>
                                ),
                                () => (
                                    <span className="truncate text-xs text-muted">
                                        @{user.username}
                                    </span>
                                ),
                            ]}
                        />
                    ),
                ]}
            />
            {/* trailing caret at the right edge; weight bold + slides on hover (mirrors "Continue →") */}
            <CaretRightIcon weight="bold" className="size-4 shrink-0 text-muted transition-transform group-hover:translate-x-1" />
        </Link>
    )
}

"use client"

import React from "react"
import { Tabs } from "@heroui/react"
import {
    HouseIcon,
    CompassIcon,
    GraduationCapIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { DASHBOARD_TABS } from "../types"
import type { DashboardTab } from "../types"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { useDashboardTabStore } from "@/hooks/zustand/dashboardTab/store"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"

/** Leading icon shown on each DashboardPage tab, keyed by tab id. */
const TAB_ICONS: Record<DashboardTab, typeof HouseIcon> = {
    overview: HouseIcon,
    explore: CompassIcon,
    courses: GraduationCapIcon,
    community: TrophyIcon,
}

/** Props for {@link DashboardTabsBar}. */
export type DashboardTabsBarProps = Record<string, never>
/**
 * Full-width DashboardPage tab strip (mirror of the profile page's `ProfileTabsBar`).
 * Registered as the global Navbar's bottom layer ({@link useRegisterNavbarBottomLayer}),
 * so the Navbar renders it flush under its primary row and owns the single bottom
 * border + sticky — this strip carries none of its own. Native HeroUI secondary
 * Tabs (foreground text + accent underline); the open tab lives in the shared
 * store so panels stay in sync. Mobile = icon only; label shows from `md` up.
 * @param props - optional root class name (placement only)
 */
export const DashboardTabsBar = () => {
    const t = useTranslations()
    const { tab, setTab } = useDashboardTabStore()

    return (
        <div className={"w-full"}>
            {/* page-pad owns the horizontal inset; py stays 0 so the strip hugs the navbar */}
            <Box principle="page-pad" className="w-full px-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <ExtendedTabs
                    selectedKey={tab}
                    onSelectionChange={(key) => setTab(key as DashboardTab)}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("DashboardPage.title")}>
                            {DASHBOARD_TABS.map((tabId) => {
                                const TabIcon = TAB_ICONS[tabId]
                                return (
                                    <Tabs.Tab
                                        key={tabId}
                                        id={tabId}
                                        aria-controls={`DashboardPage-panel-${tabId}`}
                                    >
                                        <StackH
                                            gap={2}
                                            principle="icon-text"
                                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                            align="center"
                                            items={[
                                                () => (
                                                    <TabIcon
                                                        aria-hidden
                                                        focusable="false"
                                                        className="size-5 shrink-0"
                                                    />
                                                ),
                                                () => (
                                                    <span className="hidden @app-md:inline">
                                                        {t(`DashboardPage.tabs.${tabId}`)}
                                                    </span>
                                                ),
                                            ]}
                                        />
                                        <Tabs.Indicator />
                                    </Tabs.Tab>
                                )
                            })}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </Box>
        </div>
    )
}

"use client"

import React from "react"
import {
    Icon,
} from "@iconify/react"
import {
    BadgeImage,
} from "@/components/blocks/identity/BadgeImage"
import { StackH } from "@/components/frames/Stack"

/**
 * Weekly-league tiers, lowest → highest. Mirrors the backend `LeagueTier` enum.
 * Names are picked so each maps to a *distinct, multicolor* `fluent-emoji-flat`
 * icon (medals → medal → gem → trophy → crown), escalating prestige.
 */
export enum LeagueTier {
    /** Entry tier. */
    Bronze = "bronze",
    /** Second tier. */
    Silver = "silver",
    /** Third tier. */
    Gold = "gold",
    /** Fourth tier. */
    Platinum = "platinum",
    /** Fifth tier. */
    Diamond = "diamond",
    /** Sixth tier. */
    Champion = "champion",
    /** Top tier. */
    Legend = "legend",
}

/**
 * Per-tier `fluent-emoji-flat` icon name (multicolor, no recolor needed) +
 * display label. The Iconify set ships gold/silver/bronze medals natively, so the
 * tier ladder reads as real metal/gem/crown art instead of one recolored shape.
 */
interface TierVisual {
    /** Iconify icon id (`fluent-emoji-flat:*`). */
    icon: string
    /** Human label shown next to the badge. */
    label: string
}

/** Tier → icon + label map. */
const TIER_VISUAL: Record<LeagueTier, TierVisual> = {
    [LeagueTier.Bronze]: {
        icon: "fluent-emoji-flat:3rd-place-medal",
        label: "Bronze",
    },
    [LeagueTier.Silver]: {
        icon: "fluent-emoji-flat:2nd-place-medal",
        label: "Silver",
    },
    [LeagueTier.Gold]: {
        icon: "fluent-emoji-flat:1st-place-medal",
        label: "Gold",
    },
    [LeagueTier.Platinum]: {
        icon: "fluent-emoji-flat:sports-medal",
        label: "Platinum",
    },
    [LeagueTier.Diamond]: {
        icon: "fluent-emoji-flat:gem-stone",
        label: "Diamond",
    },
    [LeagueTier.Champion]: {
        icon: "fluent-emoji-flat:trophy",
        label: "Champion",
    },
    [LeagueTier.Legend]: {
        icon: "fluent-emoji-flat:crown",
        label: "Legend",
    },
}

/** Props for {@link LeagueTierBadge}. */
export interface LeagueTierBadgeProps {
    /** Which tier to render. */
    tier: LeagueTier
    /** Icon size in px (default 24). */
    size?: number
    /** Show the tier name next to the icon. */
    showLabel?: boolean
}

/**
 * Renders a weekly-league tier as its multicolor `fluent-emoji-flat` badge,
 * optionally with the tier name. Pure presentational — drives off {@link LeagueTier}.
 * @param props - {@link LeagueTierBadgeProps}
 */
export const LeagueTierBadge = ({
    tier,
    size = 24,
    showLabel = false}: LeagueTierBadgeProps) => {
    // resolve the icon + label for this tier
    const visual = TIER_VISUAL[tier]
    return (
        <div className={"shrink-0"}>
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                align="center"
                items={[
                    () => (
                        // real art from MinIO (badges/league/<tier>.png) once uploaded; until
                        // then fall back to the multicolor fluent-emoji placeholder
                        <BadgeImage
                            objectKey={`badges/league/${tier}.png`}
                            size={size}
                            alt={visual.label}
                            fallback={(
                                <Icon
                                    icon={visual.icon}
                                    width={size}
                                    height={size}
                                    aria-label={visual.label}
                                />
                            )}
                        />
                    ),
                    ...(showLabel ? [() => (
                        <span className="text-sm font-medium text-foreground">
                            {visual.label}
                        </span>
                    )] : []),
                ]}
            />
        </div>
    )
}

