     * `flashcards/review/sessions/[sessionId]/result` route — renders
     * `FlashcardSessionStats` DIRECTLY (covers both single-deck review and
     * cross-deck due), no in-progress check (2026-07-12). Mirrors
     * `resultQuizSessionId`.
     */
    resultStudySessionId?: string
}

/**
 * Course-level flashcards WORK PANE. The mode switch + deck list live in the
 * left rail (rendered by the learn layout, same as the content-map rail); this
 * page is the right pane and reads the active surface off the URL via
 * {@link useFlashcardNav}: study mode lands on an overview (today's due queue +
 * mastery), opens a deck's SM-2 reviewer, or runs the cross-deck due session;
 * quiz mode drills the chosen deck by voice.
 *
 * Back navigation from a sub-view: the due session uses the breadcrumb's
 * clickable "Review" crumb; a deck reviewer ALSO gets its own in-pane
 * `BackLink` (teacher, 2026-07-09: "both the review and quiz sections have no
 * back button") since it's reachable via a direct `/decks/[id]` URL, same
 * reasoning as `QuizSession`'s own exit link.
 * @param {FlashcardsPageProps} props Optional wrapper placement props.
 */
export const FlashcardsPage = ({
    resumeQuizSessionId,
    resumeStudySessionId,
    resultQuizSessionId,
    resultStudySessionId}: FlashcardsPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const pathname = usePathname()
    const router = useRouter()
    const searchParams = useSearchParams()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    // owning course slug — the finished-session stats recap deep-links study
    // suggestions (RAG) back into the course with it.
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const { mode, deckId, session, goMode, goDeck, goOverview } = useFlashcardNav()
    // resumed straight into a live "Quick quiz" (quiz) or "Study cards" (review/due)
    // run (via the dedicated `flashcards/{quiz,review}/sessions/[sessionId]`
    // routes) — the session becomes a full-bleed focused work surface (its own
    // `WorkSessionHeader`), so the surrounding chrome (breadcrumb, mode tabs,
    // mobile nav, bounded column) steps aside instead of doubling up on the
    // session's own header.
    const isLive = Boolean(resumeQuizSessionId || resumeStudySessionId)
    // resolve WHICH kind a "Study cards" session id is (deck-review vs cross-deck
    // due) + the deck identity when applicable — the session already persists
    // that context server-side (teacher, 2026-07-11: "drop the deck, session
    // only" + "the session has already persisted everything"), no `deckId` query hint needed.
    const studySessionContextSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(resumeStudySessionId, courseId)
    // recap stats for THAT session — its `status` is how we tell a finished
    // (completed/abandoned) session apart from an in-progress one. A finished
    // session reached by direct URL/refresh must render the STATS recap, NOT be
    // handed to the reviewer (which would wrongly start a fresh session). The
    // sibling context query above resolves ANY status, so without this a revisit
    // used to fall through to `startSessionAndRedirect`.
    const sessionStatsSwr = useQueryMyFlashcardReviewSessionStatsBySessionIdSwr(resumeStudySessionId, courseId)
    const sessionStats = sessionStatsSwr.data
    // A revisit must resolve the session's STATUS before routing. Only a
    // POSITIVELY-confirmed `in_progress` session is handed to the reviewer /
    // DueReview (whose own effect self-resumes-or-starts). Anything else —
    // finished (completed/abandoned), not-found, or status-not-yet-known — must
    // NOT reach them, or their start-a-fresh-session effect fires and appends a
    // second `/sessions/…` (the revisit crash). Hold the skeleton until known.
    const studyStatusKnown = Boolean(courseId) && !sessionStatsSwr.isLoading
        && !studySessionContextSwr.isLoading && Boolean(studySessionContextSwr.data)
    const studyIsInProgress = sessionStats?.status === "in_progress"
    // ... and the same gate for a resumed "Quick quiz" (quiz) id: a finished
    // (completed/abandoned) or unknown session reached by direct URL/refresh must
    // render the RESULT surface, NOT be handed to the live `QuizSession` (whose
    // resume effect only accepts an in-progress session and would otherwise
    // dead-end to setup — the revisit dead-end this fixes). Status-agnostic query,
    // so a not-found id resolves too (→ the result surface's own null fallback).
    const quizSessionSwr = useQueryMyFlashcardQuizSessionBySessionIdSwr(resumeQuizSessionId, courseId)
    const quizStatusKnown = Boolean(courseId) && !quizSessionSwr.isLoading
    const quizIsInProgress = quizSessionSwr.data?.status === "in_progress"
    // quiz is enrolled-only (it spends AI credits) — gate the tab for trial viewers
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = enrollmentSwr.data?.courseEnrollmentStatus?.data?.isEnrolled === true

    // once a resumed session's status resolves to "not in progress" (finished/
    // abandoned) at the LIVE route, redirect to the dedicated RESULT route
    // (2026-07-12) instead of rendering the result surface inline here — ONE
    // place decides "is this session done" (the URL itself), so an old
    // bookmark to the live route, or a session that self-heals its stuck
    // completion on a later resume attempt, both converge on `/result`
    // instead of silently rendering results at the live URL forever (which
    // is exactly what made today's bugs hard to reproduce/trust — F5 kept
    // landing back on ambiguous state). `replace` (not `push`) — the live URL
    // was never a real navigation step the learner chose.
    useEffect(() => {
        if (!resumeStudySessionId || !studyStatusKnown || studyIsInProgress || !courseDisplayId) {
            return
        }
        router.replace(
            pathConfig().locale(locale).course(courseDisplayId).learn()
                .flashcards().due(resumeStudySessionId).result().build(),
        )
    }, [resumeStudySessionId, studyStatusKnown, studyIsInProgress, courseDisplayId, locale, router])

    useEffect(() => {
        if (!resumeQuizSessionId || !quizStatusKnown || quizIsInProgress || !courseDisplayId) {
            return
        }
        router.replace(
            pathConfig().locale(locale).course(courseDisplayId).learn()
                .flashcards().quiz(resumeQuizSessionId).result().build(),
        )
    }, [resumeQuizSessionId, quizStatusKnown, quizIsInProgress, courseDisplayId, locale, router])

    // which study-overview tab is active ("Review" / "History" / "Stats") —
    // overview only (no deck open, no due session). Seeded from `?tab=` so a
    // shared/refreshed link lands back on the same tab — mirrors QuizSession's
    // own `setupTab` (teacher, 2026-07-09: "for these numbers to actually mean
    // something, we need to add a step to build the History/Stats UI for Review").
    const [overviewTab, setOverviewTab] = useState<"overview" | "history" | "stats">(() => {
        const initial = searchParams.get("tab")
        return initial === "history" || initial === "stats" ? initial : "overview"
    })
    // Only the STUDY OVERVIEW owns the `?tab=` param. In quiz mode `QuizSession`
    // mirrors its OWN setup tab into `?tab=`, and while a deck/due session is open
    // there are no overview tabs at all — so this effect MUST NOT run then, else two
    // components write the same param with different state and clobber each other in
    // a loop (teacher, 2026-07-13: "the history side here keeps glitching the url"). Gate on the
    // exact condition the overview `TabsCard` is rendered under (mode=study, no deck,
    // not a due run).
    const overviewTabsVisible = mode === "study" && session !== "due" && !deckId
    useEffect(() => {
        if (!overviewTabsVisible) {
            return
        }
        const want = overviewTab === "overview" ? null : overviewTab
        if (searchParams.get("tab") === want) {
            return
        }
        const params = new URLSearchParams(searchParams.toString())
        if (want) {
            params.set("tab", want)
        } else {
            params.delete("tab")
        }
        const qs = params.toString()
        router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false })
    }, [overviewTabsVisible, overviewTab, pathname, searchParams, router])

    // deck name for the breadcrumb when reviewing one deck (shared SWR key with the
    // reviewer → one fetch). The reviewer owns the heavy card states.
    const { data: deckData } = useSWR(
        deckId ? ["flashcard-deck", deckId] : null,
        async () => {
            const response = await queryFlashcardDeck({
                request: { flashcardDeckId: deckId as string },
            })
            return response.data?.flashcardDeck.data ?? null
        },
    )

    // breadcrumb: a sub-view (deck / due session) inserts a clickable "Review" crumb
    // (→ overview) + names the sub-view; the overview/quiz just end at "Review".
    const isDeck = mode === "study" && Boolean(deckId)
    const isDue = mode === "study" && session === "due"
    const breadcrumb = isDeck ? (
        <LearnBreadcrumb
            current={deckData?.title ?? t("flashcard.title")}
            section={{ label: t("flashcard.title"), onPress: goOverview }}
        />
    ) : isDue ? (
        <LearnBreadcrumb
            current={t("flashcard.due.label")}
            section={{ label: t("flashcard.title"), onPress: goOverview }}
        />
    ) : (
        <LearnBreadcrumb current={t("flashcard.title")} />
    )

    // dedicated RESULT route (2026-07-12) — renders the result surface
    // directly, no in-progress check. This URL only ever means "show the
    // result"; both surfaces already handle not-found/degraded data via their
    // own `AsyncContent`.
    if (resultStudySessionId) {
        return (
            <div>
                {courseId ? (
                    <FlashcardSessionStats
                        sessionId={resultStudySessionId}
                        courseId={courseId}
                        courseDisplayId={courseDisplayId ?? ""}
                        onBack={goOverview}
                    />
                ) : (
                    // brief courseId-not-resolved-yet flash — the stats surface's OWN
                    // shape, not the full live-session skeleton (header + card +
                    // buttons is the wrong shape for a result page).
                    <FlashcardSessionStatsSkeleton />
                )}
            </div>
        )
    }
    if (resultQuizSessionId) {
        return (
            <div>
                {courseId ? (
                    <FlashcardQuizResult
                        sessionId={resultQuizSessionId}
                        courseId={courseId}
                        courseDisplayId={courseDisplayId ?? ""}
                        onBack={goOverview}
                    />
                ) : (
                    <FlashcardQuizResultSkeleton />
                )}
            </div>
        )
    }

    // live "Quick quiz" run — full-bleed work surface, its own `WorkSessionHeader`
    // IS the header, so the breadcrumb/PageHeader, mobile nav, and mode tabs
    // (all "which surface am I on" chrome) step aside; nothing to switch away
    // from mid-run. No bounded `max-w-3xl` column either — matches the sticky
    // header band spanning edge-to-edge, same as `MockInterviewSession`.
    if (isLive) {
        return (
            <div>
                {resumeStudySessionId ? (
                    !studyStatusKnown || !studyIsInProgress ? (
                        // status not settled yet, OR resolved to "not in progress" — the
                        // effect above is redirecting to `/result` in the latter case; hold
                        // the skeleton through both, never fall through to the reviewer
                        // before a POSITIVELY-confirmed in-progress session.
                        <FlashcardReviewerSkeleton />
                    ) : studySessionContextSwr.data?.kind === "deck" && studySessionContextSwr.data.deckId ? (
                        <FlashcardReviewer
                            key={studySessionContextSwr.data.deckId}
                            deckId={studySessionContextSwr.data.deckId}
                            sessionId={resumeStudySessionId}
                            onBack={goOverview}
                        />
                    ) : (
                        <DueReview onExit={goOverview} sessionId={resumeStudySessionId} />
                    )
                ) : !quizStatusKnown || !quizIsInProgress ? (
                    // status not settled yet, OR resolved to "not in progress" — the effect
                    // above is redirecting to `/result` in the latter case; hold the
                    // skeleton through both, never hand a maybe-finished session to the
                    // live QuizSession (whose resume effect only accepts in-progress).
                    <QuizSessionSkeleton />
                ) : courseId ? (
                    <QuizSession
                        key={courseId}
                        courseId={courseId}
                        resumeSessionId={resumeQuizSessionId}
                    />
                ) : null}
            </div>
        )
    }

    return (
        <div>
            {/* header → content = gap-10 (named exception, fe/foundations/gap.md) —
                everything under the header is ONE gap-6 content cluster */}
            <div className={"mx-auto flex max-w-3xl flex-col gap-10"}>
                <PageHeader
                    breadcrumb={breadcrumb}
                    title={t("flashcard.title")}
                    description={t("flashcard.subtitle")}
                />

                <StackV
                    gap={6}
                    items={[
                        () => <FlashcardMobileNav />,
                        () => (
                            <div className="hidden @app-lg:block">
                                <TabsCard
                                    variant="primary"
                                    leftTabs={{
                                        items: [
                                            { key: "study", label: t("flashcard.mode.study") },
                                            { key: "quiz", label: t("flashcard.mode.quiz") },
                                        ],
                                        selectedKey: mode,
                                        ariaLabel: t("flashcard.title"),
                                        onSelectionChange: (key) => goMode(key as FlashcardMode),
                                    }}
                                />
                            </div>
                        ),
                        () => (
                            mode === "study" ? (
                                session === "due" ? (
                                    <DueReview onExit={goOverview} />
                                ) : deckId ? (
                                    // keyed so switching decks resets the reviewer's local state
                                    <FlashcardReviewer key={deckId} deckId={deckId} onBack={goOverview} />
                                ) : (
                                    <StackV
                                        gap={6}
                                        items={[
                                            () => (
                                                <TabsCard
                                                    variant="secondary"
                                                    className="w-full"
                                                    leftTabs={{
                                                        items: [
                                                            { key: "overview", label: t("flashcard.review.overviewTabOverview") },
                                                            { key: "history", label: t("flashcard.review.overviewTabHistory") },
                                                            { key: "stats", label: t("flashcard.review.overviewTabStats") },
                                                        ],
                                                        selectedKey: overviewTab,
                                                        ariaLabel: t("flashcard.review.overviewTabOverview"),
                                                        onSelectionChange: (key) => setOverviewTab(key as "overview" | "history" | "stats"),
                                                    }}
                                                />
                                            ),
                                            () => (
                                                overviewTab === "history" ? (
                                                    courseId ? (
                                                        <FlashcardReviewHistory
                                                            courseId={courseId}
                                                            onStartReview={() => setOverviewTab("overview")}
                                                        />
                                                    ) : null
                                                ) : overviewTab === "stats" ? (
                                                    courseId ? (
                                                        <FlashcardReviewStats
                                                            courseId={courseId}
                                                            onStartReview={() => setOverviewTab("overview")}
                                                        />
                                                    ) : null
                                                ) : (
                                                    <>
                                                        {/* today's spaced-repetition queue + mastery overview */}
                                                        <DueReviewHero />
                                                        <FlashcardStatsStrip />
                                                        {/* deck topic picker — now in the pane (rail dropped) */}
                                                        <FlashcardDeckList onSelectDeck={goDeck} />
                                                    </>
                                                )
                                            ),
                                        ]}
                                    />
                                )
                            ) : !isEnrolled ? (
                                // trial viewer → lock the quiz behind an enroll CTA
                                <EnrollGate
                                    title={t("flashcard.quiz.gateTitle")}
                                    description={t("flashcard.quiz.gateDescription")}
                                />
                            ) : courseId ? (
                                // a fixed-length random session over the whole course (no per-deck
                                // topic pick); keyed by course so it resets
                                <QuizSession
                                    key={courseId}
                                    courseId={courseId}
                                    resumeSessionId={resumeQuizSessionId}
                                />
                            ) : null
                        ),
                    ]}
                />
            </div>
        </div>
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    WeeklyBoard,
} from "./WeeklyBoard"
import {
    GlobalBoard,
} from "./GlobalBoard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
/** The two leaderboard scopes the page can show. */
enum LeagueTab {
    Weekly = "weekly",
    Global = "global",
}

/** Props for {@link LeaguePage}. */
export type LeaguePageProps = Record<string, never>
/**
 * The full leaderboard page behind the dashboard `LeagueCard`'s "see more":
 * a proper main page ({@link PageHeader} + responsive breadcrumb, per
 * `header.md` — no bare `<h1>`) with two page-level tabs — the weekly-league
 * cohort ("this week") and the global all-users board ("global"). The tabs
 * switch the WHOLE board panel, so they're a `TabsCard variant="primary"`
 * segmented pill (`tabs.md §0b`), not a filter underline. Each board
 * self-fetches; only the active one mounts (the inactive leaf query stays
 * idle). `"use client"` for tab state + breadcrumb nav.
 *
 * @param props - optional className for the root element.
 */
export const LeaguePage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const [tab, setTab] = useState<LeagueTab>(LeagueTab.Weekly)

    return (
        <div className={"mx-auto w-full max-w-2xl p-3"} data-principle="cell-pad">
            <StackV
                gap={7}
                principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={(
                                <ResponsiveBreadcrumb
                                    items={[
                                        {
                                            key: "home",
                                            label: t("nav.home"),
                                            onPress: () => router.push(pathConfig().locale(locale).build()),
                                        },
                                        { key: "league", label: t("dashboard.league.pageTitle") },
                                    ]}
                                />
                            )}
                            title={t("dashboard.league.pageTitle")}
                        />
                    ),
                    // tabs + board grouped at block-boundary; only the active board mounts
                    () => (
                        <StackV
                            gap={6}
                            principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        variant="primary"
                                        leftTabs={{
                                            items: [
                                                { key: LeagueTab.Weekly, label: t("dashboard.league.tabWeekly") },
                                                { key: LeagueTab.Global, label: t("dashboard.league.tabGlobal") },
                                            ],
                                            selectedKey: tab,
                                            ariaLabel: t("dashboard.league.pageTitle"),
                                            onSelectionChange: (key) => setTab(String(key) as LeagueTab),
                                        }}
                                    />
                                ),
                                () => (tab === LeagueTab.Weekly ? <WeeklyBoard /> : <GlobalBoard />),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

"use client"

import React, { useEffect } from "react"
import { Card, CardContent, Link } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter, useSearchParams } from "next/navigation"
import { SignInSection } from "@/components/overlays/modals/AuthenticationModal/SignInSection"
import { SignUpSection } from "@/components/overlays/modals/AuthenticationModal/SignUpSection"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { AuthenticationModalTab, resetAuthenticationModalTab } from "@/redux/slices/tabs"
import { resetSignInState, resetSignUpState } from "@/redux/slices/state"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link LoginPage}. */
export type LoginPageProps = Record<string, never>
/**
 * `/login` — the auth-guard redirect target for protected routes (`src/proxy.ts`),
 * and a directly-navigable sign-in/sign-up page. Reuses the SAME sign-in/sign-up
 * step components as {@link AuthenticationModal} (Credentials/OTP, Registration/Otp) —
 * only the chrome differs (no close button, a page shell instead of a dialog).
 *
 * On successful auth, resumes at `?redirect=<path>` (set by the edge guard) or the
 * dashboard by default.
 *
 * @param props - {@link LoginPageProps}
 */
export const LoginPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const searchParams = useSearchParams()

    const authenticationModalTab = useAppSelector((state) => state.tabs.authenticationModalTab)
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)

    const rawRedirect = searchParams.get("redirect")
    // Only ever resume to an internal path — never let a query param send the visitor off-site.
    const redirectTarget = rawRedirect && rawRedirect.startsWith("/") && !rawRedirect.startsWith("//")
        ? rawRedirect
        : undefined

    // Always land on Sign-in + a clean step, regardless of whatever the modal was left at elsewhere.
    useEffect(() => {
        dispatch(resetAuthenticationModalTab())
        dispatch(resetSignInState())
        dispatch(resetSignUpState())
    }, [dispatch])

    // Credentials/OTP success flips `keycloak.authenticated` in place (no navigation of its
    // own, since the modal variant just closes) — this page resumes the originally-requested
    // route once that happens. The OAuth round-trip resumes separately via `OauthRedirect`.
    useEffect(() => {
        if (!authenticated) {
            return
        }
        router.replace(redirectTarget ?? pathConfig().locale(locale).dashboard().build())
    }, [authenticated, redirectTarget, router, locale])

    const renderSection = () => {
        switch (authenticationModalTab) {
        case AuthenticationModalTab.SignIn:
            return <SignInSection hideCloseButton />
        case AuthenticationModalTab.SignUp:
            return <SignUpSection hideCloseButton />
        }
    }

    return (
        <Box principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            className={"mx-auto max-w-2xl p-6 py-16"}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <StackH gap={1} principle="name-handle"
                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                            justify="center" items={[
                                () => (
                                    <Link
                                        href={pathConfig().locale(locale).home().build()}
                                        className="font-semibold text-lg"
                                    >
                                        {t("nav.brand")}
                                    </Link>
                                ),
                            ]} />
                    ),
                    () => (redirectTarget ? (
                        <div className="text-center text-xs text-muted">
                            {authenticationModalTab === AuthenticationModalTab.SignUp
                                ? t("auth.signUp.desc")
                                : t("auth.signIn.desc")}
                        </div>
                    ) : null),
                    () => (
                        <Card>
                            <CardContent>
                                {renderSection()}
                            </CardContent>
                        </Card>
                    ),
                ]} />
        </Box>
    )
}

import React from "react"
import { MapTrifoldIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@/components/blocks/learn/MindMapRail"
import { MindMapContinueButton } from "@/components/blocks/learn/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@/components/blocks/learn/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@/components/composites/stats/Legend"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { type ComponentTypeWithSkeleton, type SkeletonProps } from "@/components/frames/_slot"
import { ResizableRail } from "@/components/behaviors/ResizableRail"
import { StackH, StackV } from "@/components/frames/Stack"
import { Stage } from "@/components/frames/Stage"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { FillAvailable } from "@/components/frames/FillAvailable"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * SCREEN — `_MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list and the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose).
 *
 * The graph engine arrives as the `canvas` slot. This screen lays out the rail,
 * the floating chrome and the empty state; it does not know ReactFlow exists.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 *
 * PRESENTATIONAL — every input arrives as a prop; the connected `index.tsx`
 * owns the fetch, the rail's filter state, and every `t()` call (`split.md`).
 *
 * Emits its own identity (`data-tier="page"` / `data-component="MindMapPage"`)
 * unconditionally on its root, same as `_ModulePage`/`_ContentPage` — see
 * `split.md`'s "Identity is data-tier + data-component" section.
 *
 * The viewport-relative full-bleed height, the canvas's floating-chrome
 * anchoring, and the rail's scroll region are all composed on `Stage` /
 * `ScrollArea` (`@/components/frames/Stage`, `@/components/frames/ScrollArea`)
 * — the two frames the vocabulary gap this screen flagged in a previous pass
 * was built to close. No raw `className` shape remains on this page.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean

    /**
     * The graph itself, mounted by the caller. A screen composes; it does not own a
     * rendering engine — and an earlier pass left a literal placeholder here instead
     * of a slot, which meant wiring this screen would have shipped a mind-map page
     * with no map in it.
     */
    canvas: ComponentTypeWithSkeleton
    /**
     * The empty state's one way forward — browse the course's modules instead.
     * Omit → the empty state states the fact and offers nothing, which is right
     * only when there is nowhere useful to send the reader.
     */
    onBrowseModules?: () => void
    /** Every word the whole-screen empty state says — resolved by the connected half. */
    labels: MindMapPageLabels
}

/** All display text this screen owns, already localized by the connected half. */
export interface MindMapPageLabels {
    /** Heading when the course has no authored map yet. */
    emptyTitle: string
    /** Body when the course has no authored map yet. */
    emptyDescription: string
    /** Label on the empty state's way forward, paired with {@link MindMapPageProps.onBrowseModules}. */
    emptyCta: string
}

/** localStorage key + bounds the real workspace persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

/** This screen's own identity — handed down to whichever `Stage` is the root, per branch, instead of a wrapping div (BLOCK-2). See `_identity.ts`. */
const MIND_MAP_PAGE_IDENTITY: CallerIdentity = { tier: "page", component: "MindMapPage" }

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case. The
 * viewport-relative full-bleed height is `Stage`'s `fill="viewport"` — the
 * same shape the real spine below uses for the same reason.
 */
const MindMapWorkspaceEmpty = ({ labels, onBrowseModules }: MindMapWorkspaceEmptyProps) => (
    <Stage
        fill="viewport"
        identity={MIND_MAP_PAGE_IDENTITY}
        canvas={() => (
            <StackV
                gap={1}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="center"
                items={[() => (
                    <AsyncContentEmpty

                        icon={MapTrifoldIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                        onRetry={onBrowseModules}
                        retryLabel={labels.emptyCta}
                    />
                )]}
            />
        )}
    />
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const _MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
    canvas: Canvas,
    onBrowseModules,
    labels,
}: MindMapPageProps) => {
    // Built as a thunk, called only for the non-empty branch below — mirrors
    // `_ModulePage`'s `spine(isSkeleton)`, so the empty branch never pays for
    // building a tree it will not render.
    const workspace = () => {
        const railSection = (
            <MindMapRail

                query={query}
                onQuery={onQuery}
                tier={tier}
                onTier={onTier}
                items={items}
                selectedId={selectedId}
                onPick={onPick}
                isLoading={isRailLoading}
                ariaLabel={railAriaLabel}
                tierAriaLabel={railTierAriaLabel}
                isSkeleton={isSkeleton}

            />
        )

        // The canvas region's floating chrome — in the real app these render as the
        // SAME ReactFlow engine's own Panel children. Only present (`standalone`,
        // resting) — `Stage` skips a slot entirely when it is `undefined`.
        const showOverlays = variant === "standalone" && !isSkeleton

        const topCenterSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapContinueButton

                            resumeHref={resumeHref}
                            allContentDone={allContentDone}
                            onResume={onResume}
                            continueAriaLabel={continueAriaLabel}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        const bottomStartSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => <Legend items={legendItems} />]}
                />
            )
            : undefined

        const bottomEndSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapFullscreenButton

                            onZoomIn={onZoomIn}
                            onZoomOut={onZoomOut}
                            onToggleFullscreen={onToggleFullscreen}
                            isFullscreen={isFullscreen}
                            ariaLabels={fullscreenAriaLabels}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
        // floating chrome that in the real app renders as the SAME engine's own Panel
        // children. `Stage` owns the positioning context and the three floating anchors —
        // no page-level `relative`/`absolute` left.
        const canvasStage = (
            <FillAvailable
                at="base"
                explain="Canvas stage consumes remaining workspace width beside the resizable rail — not a fixed-size peer."
                body={() => (
                    <Stage
                        canvas={Canvas}
                        topCenter={topCenterSlot}
                        bottomStart={bottomStartSlot}
                        bottomEnd={bottomEndSlot}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        )

        const workspaceRail = (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={railResizeAriaLabel}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <ScrollArea
                    axis="y"
                    isSkeleton={isSkeleton}
                    body={({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            padding={6}
                            principle="page-pad"
                            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                            gap={1}
                            classNames={["h-full"]}
                            isSkeleton={isSkeleton}
                            items={[() => railSection]}
                        />
                    )}
                />
            </ResizableRail>
        )

        const workspaceSections = (
            <>
                {variant === "workspace" ? workspaceRail : null}
                {canvasStage}
            </>
        )

        // The viewport-relative full-bleed height — the shell's own chrome height
        // subtracted — is `Stage`'s `fill="viewport"`; the rail + canvas row is its
        // `canvas` slot (a stage need not be a literal drawing surface — see the
        // frame's own file header for why this is the shape it names).
        return (
            <Stage
                fill="viewport"
                isSkeleton={isSkeleton}
                identity={MIND_MAP_PAGE_IDENTITY}
                canvas={({ isSkeleton }: SkeletonProps) => (
                    <StackH gap={1} isSkeleton={isSkeleton} items={[() => workspaceSections]} />
                )}
            />
        )
    }

    return variant === "workspace" && isEmpty
        ? <MindMapWorkspaceEmpty labels={labels} onBrowseModules={onBrowseModules} />
        : workspace()
}

export { _MindMapPage }

type MindMapWorkspaceEmptyProps = {
    labels: MindMapPageLabels
    onBrowseModules?: () => void
}

