} from "../utils"
import {
    DetailRow,
} from "../DetailRow"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Right-hand panel: the price card plus the bank/account/amount/content rows.
 *
 * Self-contained section (single-use): reads its own checkout query params,
 * derives the destination bank from the QR url, and owns the clipboard copy
 * handler — so the checkout container only renders `<OrderSummary />` and the
 * logic lives next to where it is used. `"use client"` for the query-params /
 * i18n hooks and the interactive copy rows. The repeated rows are rendered via
 * the presentational {@link DetailRow} (list-style), which takes the local
 * `onCopy` handler as a prop.
 */
export const OrderSummary = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()

    const amount = searchParams.get("amount") || ""
    const referenceId = searchParams.get("ref") || ""
    const courseTitle = searchParams.get("courseTitle") || ""
    const qrUrl = searchParams.get("qr") || ""

    /** Destination bank + account parsed once from the QR url. */
    const bankDetails = useMemo<BankDetails>(
        () => parseBankDetails(qrUrl),
        [
            qrUrl,
        ],
    )

    /** Copy the given text to the clipboard. */
    const onCopy = useCallback(
        (text: string) => {
            void navigator.clipboard.writeText(text)
        },
        [],
    )

    return (
        <StackV identity={{ tier: "page", component: "OrderSummary" }} gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <Card className="bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <h3 className="mb-4 text-lg font-medium">{courseTitle}</h3>
                                <StackH gap={3} principle="value-row" align="baseline"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    items={[
                                        () => (
                                            <span className="text-3xl font-bold text-primary">
                                                {Number(amount).toLocaleString("vi-VN")}
                                            </span>
                                        ),
                                        () => <span className="text-sm text-muted">VND</span>,
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),

                () => (
                    <Card className="flex-grow bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <StackV gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <DetailRow label={t("payment.sepay.bank")} value={bankDetails.bank} />,
                                        () => (
                                            <DetailRow
                                                copyValue={bankDetails.account}
                                                label={t("payment.sepay.account")}
                                                showCopy
                                                value={bankDetails.account}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={amount}
                                                label={t("payment.sepay.amount")}
                                                showCopy
                                                value={`${Number(amount).toLocaleString("vi-VN")} VND`}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={referenceId}
                                                isHighlighted
                                                label={t("payment.sepay.content")}
                                                showCopy
                                                value={referenceId}
                                                onCopy={onCopy}
                                            />
                                        ),
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),
            ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CpuIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AiKeyHealthGroup } from "@/modules/api/graphql/queries/types/ai-key-health"

/** Props for {@link AiKeyGroup}. */
export interface AiKeyGroupProps {
    /** One per-model AI key health group from GraphQL. */
    group: AiKeyHealthGroup
}

/**
 * One model group of AI keys on the public status page. Header reads
 * "<models> · <provider> · healthy/total keys"; below it a row of masked key
 * chips, each tinted success (healthy) or danger (unhealthy). Token-only colors
 * → works light + dark. The masked label (`sk-...x9f`) is all that is shown.
 *
 * List item: keeps its own `group` payload but reads its own labels from i18n.
 * @param props.group - Masked AI key health for one model.
 */
export const AiKeyGroup = ({ group }: AiKeyGroupProps) => {
    const t = useTranslations("status")

    const header = useMemo(() => {
        const models = group.models.join(", ") || group.provider
        return t("aiKeyGroupHeader", {
            models,
            provider: group.provider,
            healthy: group.healthyKeys,
            total: group.totalKeys,
        })
    }, [group, t])

    const chipItems = group.keys.map((key, index) => () => (
        <span
            key={`${key.keyMask}-${index}`}
            className={cn(
                "inline-flex items-center rounded-full px-2 py-0 font-mono text-xs font-medium",
                key.healthy
                    ? "bg-success-soft text-success-soft-foreground"
                    : "bg-danger-soft text-danger-soft-foreground",
            )}
        >
            {key.keyMask}
        </span>
    ))

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        gap={4}
                        principle="label-field"
                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    align="center"
                                    items={[
                                        () => (
                                            <CpuIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-4 shrink-0 text-muted"
                                            />
                                        ),
                                        () => (
                                            <span className="text-sm font-medium text-foreground">
                                                {header}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            () => (group.keys.length > 0 ? (
                                <Cluster gap={3} principle="chip-row" items={chipItems}
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                />
                            ) : (
                                <span className="text-xs text-muted">{t("noKeys")}</span>
                            )),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent } from "@heroui/react"
import { useTranslations } from "next-intl"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveComponentStatusVisual } from "../map"
import type { SystemHealthComponent } from "@/modules/api/graphql/queries/types/system-health-status"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"

/** Props for {@link ComponentCard}. */
export interface ComponentCardProps {
    /** One probed infrastructure component from GraphQL. */
    component: SystemHealthComponent
}

/**
 * A single infrastructure component card on the public status page — status dot
 * + name, a status chip, latency ("12ms"), and a relative last-checked time.
 *
 * List item: keeps its own `component` payload but reads its own status labels
 * + relative-time strings from the i18n hooks (no prop-drilled maps).
 * @param props.component - Probed component snapshot.
 */
export const ComponentCard = ({ component }: ComponentCardProps) => {
    const t = useTranslations()
    const visual = resolveComponentStatusVisual(component.status)

    const statusLabel = t(`status.componentStatus.${component.status}`)

    const checkedAgo = useMemo(
        () => getTimeAgoLabel(getTimeAgoMessage(component.checkedAt), t),
        [component.checkedAt, t],
    )

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        gap={3}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center"
                                    justify="between"
                                    items={[
                                        () => (
                                            <StackH
                                                gap={3}
                                                principle="identity"
                                                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                align="center"
                                                classNames={["min-w-0"]}
                                                items={[
                                                    () => (
                                                        <span
                                                            className={`size-2.5 shrink-0 rounded-full ${visual.dotClassName}`}
                                                            aria-hidden
                                                        />
                                                    ),
                                                    () => (
                                                        <span className="truncate font-mono text-sm font-medium text-foreground">
                                                            {component.name}
                                                        </span>
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StatusChip tone={visual.tone} icon={visual.icon}>
                                                {statusLabel}
                                            </StatusChip>
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center"
                                    justify="between"
                                    items={[
                                        () => (
                                            <span className="tabular-nums text-xs text-muted">
                                                {component.latencyMs === null
                                                    ? "—"
                                                    : t("status.latency", { ms: component.latencyMs })}
                                            </span>
                                        ),
                                        () => (
                                            <span className="truncate text-xs text-muted">
                                                {t("status.checked", { ago: checkedAgo })}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            ...(component.message ? [() => (
                                <p className="truncate text-xs text-danger-soft-foreground" title={component.message ?? undefined}>
                                    {component.message}
                                </p>
                            )] : []),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SystemStatusSkeleton}. */
export interface SystemStatusSkeletonProps extends WithClassNames<undefined> {
    /** When true, render only the AI key group mirror (the AI section loads on its own). */
    aiOnly?: boolean
}

/** A single component-card placeholder mirroring {@link ComponentCard}. */
const ComponentCardSkeleton = () => (
    <Box principle="card-padding" className="rounded-large bg-surface p-4 shadow-surface"
        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        align="center"
                        justify="between"
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    align="center"
                                    items={[
                                        () => <Skeleton className="size-2.5 rounded-full" />,
                                        () => <Skeleton className="h-4 w-20 rounded" />,
                                    ]}
                                />
                            ),
                            () => <Skeleton className="h-5 w-16 rounded-full" />,
                        ]}
                    />
                ),
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        align="center"
                        justify="between"
                        items={[
                            () => <Skeleton className="h-3 w-10 rounded" />,
                            () => <Skeleton className="h-3 w-24 rounded" />,
                        ]}
                    />
                ),
            ]}
        />
    </Box>
)

/** A single AI key group placeholder mirroring {@link AiKeyGroup}. */
const AiKeyGroupSkeleton = () => (
    <Box principle="card-padding" className="rounded-large bg-surface p-4 shadow-surface"
        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
        <StackV
            gap={4}
            principle="label-field"
            explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
            items={[
                () => <Skeleton className="h-4 w-2/3 rounded" />,
                () => (
                    <Cluster
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={Array.from({ length: 5 }, (_, index) => () => (
                            <Skeleton key={index} className="h-5 w-20 rounded-full" />
                        ))}
                    />
                ),
            ]}
        />
    </Box>
)

/**
 * Loading mirror for {@link import("../index").SystemStatus}. Matches the real
 * banner + infrastructure grid + AI key group rhythm so the layout never jumps
 * when data resolves. Pass `aiOnly` to mirror just the AI section.
 */
export const SystemStatusSkeleton = ({ aiOnly = false }: SystemStatusSkeletonProps) => {
    if (aiOnly) {
        return (
            <StackV identity={{ tier: "page", component: "SystemStatusSkeleton" }}
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={Array.from({ length: 2 }, (_, index) => () => (
                    <AiKeyGroupSkeleton key={index} />
                ))}
            />
        )
    }

    const gridItems: Array<GridItem> = Array.from({ length: 6 }, (_, index) => ({
        key: String(index),
        content: () => <ComponentCardSkeleton />,
    }))

    return (
        <StackV identity={{ tier: "page", component: "SystemStatusSkeleton" }}
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => <Skeleton className="h-14 w-full rounded-2xl" />,
                () => (
                    <StackV
                        gap={4}
                        principle="label-field"
                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => <Skeleton className="h-4 w-32 rounded" />,
                            () => (
                                <Grid
                                    columns={{ base: 1, sm: 2, lg: 3 }}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={gridItems}
                                />
                            ),
                        ]}
                    />
                ),
            ]}
        />
    )
}
